NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'John'

CHAPTERS = {
    1: {
        1: 'Am Anfang war das Wort, und das Wort war bei Gott, und das Wort war Gott.',
        2: 'Dieses war am Anfang bei Gott.',
        3: 'Alles ist dadurch entstanden, und ohne es ist auch nicht eines geworden. Was geworden ist',
        4: 'in ihm, war Leben, und das Leben war das Licht der Menschen.',
        5: 'Und das Licht scheint in der Finsternis, und die Finsternis hat es nicht erfasst.',
        6: 'Es kam ein Mensch, von Gott gesandt, sein Name [war] Johannes.',
        7: 'Dieser kam zum Zeugnis, um Zeugnis abzulegen über das Licht, damit alle durch ihn glauben.',
        8: 'Jener war nicht das Licht, sondern [er kam], um Zeugnis abzulegen über das Licht.',
        9: 'Er war das wahre Licht, das jeden Menschen erleuchtet, der zur Welt kommt.',
        10: 'Er war in der Welt, und die Welt ist durch ihn geworden, aber die Welt erkannte ihn nicht.',
        11: 'In das Seine kam er, aber die Seinen nahmen ihn nicht an.',
        12: 'Alle aber, die ihn annahmen, denen gab er Vollmacht, Kinder Gottes zu werden – denen, die an seinen Namen glauben,',
        13: 'die weder aus Blut noch aus dem Willen des Fleisches noch aus dem Willen eines Mannes, sondern aus Gott geboren wurden.',
        14: 'Und das Wort wurde Fleisch, und er zeltete unter uns, und wir schauten seine Herrlichkeit, eine Herrlichkeit wie die des einzigen [Sohnes] beim Vater, voller Gnade und Wahrheit.',
        15: '(Johannes legt Zeugnis ab über ihn, und er hat gerufen und gesagt: „Er war es, von dem ich gesagt habe: ‚Der nach mir kommt, ist vor mir gewesen, denn er war eher da als ich.‘“)',
        16: 'Denn aus seiner Fülle haben wir alle erhalten, und zwar Gnade über Gnade;',
        17: 'denn das Gesetz wurde durch Mose gegeben, Gnade und Wahrheit sind durch Jesus Christus gekommen.',
        18: 'Niemand hat Gott jemals gesehen; der Einzige, Gott, der an der Brust des Vaters ist, der hat [ihn] beschrieben.',
        19: 'Und dies ist das Zeugnis von Johannes, als die Judäer aus Jerusalem Priester und Leviten zu ihm sandten, um ihn zu fragen: „Wer bist du?“',
        20: 'Und er bekannte und leugnete nicht, und zwar bekannte er: „Ich bin nicht der Gesalbte.“',
        21: 'Und sie fragten ihn: „Was dann? Bist du Elija?“Und er sagt: „Bin ich nicht.“„Bist du der Prophet?“Und er antwortete: „Nein.“',
        22: 'Darauf sagten sie zu ihm: „Wer bist du? … damit wir denen eine Antwort geben, die uns geschickt haben. Was sagst du über dich selbst?“',
        23: 'Er sagte: „Ich [bin] die Stimme eines Rufers in der Wüste: ‚Ebnet den Weg des Herrn!‘, genau wie der Prophet Jesaja gesagt hat.“',
        24: 'Und sie waren Abgesandte von den Pharisäern.',
        25: 'Und sie fragten ihn, und sie sagten zu ihm: „Warum taufst du dann, wenn du weder der Gesalbte noch Elija noch der Prophet bist?“',
        26: 'Johannes antwortete ihnen und sagte: „Ich taufe mit Wasser; [aber] mitten unter euch steht einer, den ihr nicht kennt,',
        27: 'der nach mir kommt; ich bin nicht [einmal] würdig, seinen Schuhriemen zu lösen.“',
        28: 'Dies geschah in Betanien, jenseits des Jordans, wo Johannes war und taufte.',
        29: 'Am nächsten [Tag] sieht er Jesus auf sich zukommen, und er sagt: „Siehe!, das Lamm Gottes, das die Sünde der Welt fortnimmt.',
        30: 'Dieser ist es, über den ich gesagt habe: ‚Nach mir kommt ein Mann, der vor mir gewesen ist, denn er war eher da als ich‘;',
        31: 'auch ich kannte ihn nicht, doch damit er Israel bekannt wird, deshalb bin ich gekommen und taufe mit Wasser.“',
        32: 'Und Johannes legte Zeugnis ab und sagte: „Ich habe den Geist vom Himmel herabsteigen sehen wie eine Taube, und er blieb auf ihm.',
        33: 'Auch ich kannte ihn nicht, doch der mich geschickt hat, mit Wasser zu taufen, der hat zu mir gesagt: ‚Auf wen auch immer du den Geist herabsteigen und auf ihm bleiben siehst, der ist es, der mit dem heiligen Geist tauft.‘',
        34: 'Und ich habe es gesehen, und ich habe bezeugt, dass dieser der Sohn Gottes ist.“',
        35: 'Am folgenden [Tag] stand Johannes wieder da, und zwei von seinen Jüngern,',
        36: 'und als er Jesus vorbeigehen sah, sagt er: „Siehe!, das Lamm Gottes.“',
        37: 'Und die beiden Jünger hörten ihn reden, und sie folgten Jesus.',
        38: 'Als nun Jesus sich umdrehte und sah, dass sie [ihm] folgten, sagt er zu ihnen: „Was sucht ihr?“Sie aber sagten zu ihm: „Rabbi (das heißt übersetzt: Lehrer), wo hältst du dich auf?“',
        39: 'Er sagt zu ihnen: „Kommt, dann werdet ihr sehen!“Sie kamen also, und sie sahen, wo er sich aufhielt, und jenen Tag blieben sie bei ihm; es war etwa die zehnte Stunde.',
        40: 'Andreas, der Bruder von Simon Petrus, war einer von den beiden, die es von Johannes gehört hatten und ihm gefolgt waren.',
        41: 'Dieser findet als erstes seinen Bruder Simon, und er sagt zu ihm: „Wir haben den Messias (das bedeutet übersetzt: Gesalbter) gefunden!“',
        42: 'Er brachte ihn zu Jesus. Jesus sah ihn an und sagte: „Du bist Simon, der Sohn des Johannes, du sollst Kephas genannt werden!“(was sich übersetzen lässt: Petrus.)',
        43: 'Am nächsten [Tag] wollte er nach Galiläa aufbrechen, und er findet Philippus. Und Jesus sagt zu ihm: „Folge mir!“',
        44: '(Nun war Philippus aus Betsaïda, aus der Stadt von Andreas und Petrus.)',
        45: 'Philippus findet Natanaël, und er sagt zu ihm: „Wir haben den gefunden, von dem Mose im Gesetz und die Propheten geschrieben haben: Jesus von Nazaret, Sohn des Josef.“',
        46: 'Und Natanaël sagte zu ihm: „Kann aus Nazaret etwas Gutes stammen?“Philippus sagt zu ihm: „Komm und sieh!“',
        47: 'Jesus sah Natanaël auf sich zukommen, und er sagt über ihn: „Siehe!, tatsächlich ein Israelit, in dem keine Falschheit ist.“',
        48: 'Natanaël sagt zu ihm: „Woher kennst du mich?“Jesus antwortete und sagte zu ihm: „Bevor dich Philippus rief, als du unter dem Feigenbaum warst, habe ich dich gesehen.“',
        49: 'Natanaël antwortete ihm: „Rabbi, du bist der Sohn Gottes, du bist der König Israels!“',
        50: 'Jesus antwortete, und er sagte zu ihm: „Weil ich dir gesagt habe, dass ich dich unter dem Feigenbaum sah, glaubst du? Größeres als das wirst du sehen.“',
        51: 'Und er sagt zu ihm: „Amen, amen, ich sage euch: Ihr werdet den Himmel geöffnet sehen und die Engel Gottes auf- und absteigen über dem Menschensohn.“',
    },
    2: {
        1: 'Und am dritten Tag fand statt eine Hochzeit in Kana in Galiläa, und die Mutter von Jesus war dort;',
        2: 'es wurde aber auch Jesus samt seinen Jüngern eingeladen zu der Hochzeit.',
        3: 'Und als der Wein ausgegangen war, sagt die Mutter von Jesus zu ihm: „Sie haben keinen Wein!“',
        4: 'Und Jesus sagt zu ihr: „Was ‹habe ich mit dir zu schaffen›, Frau? Noch ist meine Stunde nicht gekommen.“',
        5: 'Seine Mutter sagt zu den Dienern: „Was auch immer er euch sagt, das tut!“',
        6: 'Nun waren dort sechs steinerne Wasserkrüge aufgestellt (gemäß der [rituellen] Reinigung der Judäer), die fassten jeweils zwei oder drei Maß.',
        7: 'Jesus sagt zu ihnen: „Füllt die Wasserkrüge mit Wasser!“Und sie füllten sie bis oben hin.',
        8: 'Und er sagt zu ihnen: „Jetzt schöpft es und bringt es dem Zeremonienmeister!“Sie aber brachten es hin.',
        9: 'Als nun der Zeremonienmeister das Wasser kostete, das zu Wein geworden war und er nicht wusste, woher es stammte – die Diener hingegen, die das Wasser geschöpft hatten, wussten es –, da ruft der Zeremonienmeister den Bräutigam',
        10: 'und er sagt zu ihm: „Jeder Mensch serviert zuerst den guten Wein, und wann immer sie betrunken sind, den schlechteren; du hast den guten Wein bis jetzt aufgehoben.“',
        11: 'Diesen Anfang der Zeichen machte Jesus in Kana in Galiläa, und er gab seine Herrlichkeit zu erkennen, und seine Jünger glaubten an ihn.',
        12: 'Danach stieg er hinab nach Kafarnaum, er und seine Mutter und seine Geschwister und seine Jünger; und dort blieben sie ‹ein paar› Tage.',
        13: 'Und das Passa der Judäer war nahe, und Jesus stieg hinauf nach Jerusalem.',
        14: 'Und er fand im Tempel [Händler], die Rinder und Schafe und Tauben verkauften, und die Geldwechsler, die dabeisaßen,',
        15: 'und nachdem er eine Peitsche aus Stricken gemacht hatte, trieb er sie alle aus dem Tempel hinaus, samt den Schafen und den Rindern, und von den Geldwechslern schüttete er das Geld fort und stieß die Tische um,',
        16: 'und zu denen, die die Tauben verkauften, sagte er: „Schafft diese [Dinge] weg von hier! Macht das Haus meines Vaters nicht zu einer Markthalle! “',
        17: '(Seine Jünger erinnerten sich daran, dass geschrieben steht: „Der Eifer für dein Haus wird mich verzehren.“)',
        18: 'Darauf antworteten die Judäer und sagten zu ihm: „Was für ein Zeichen zeigst du uns, dass du diese [Dinge] tun darfst?“',
        19: 'Jesus antwortete und sagte zu ihnen: „Zerstört diesen Tempel, und in drei Tagen werde ich ihn errichten!“',
        20: 'Darauf sagten die Judäer: „In sechsundvierzig Jahren wurde dieser Tempel gebaut, und du wirst ihn in drei Tagen errichten?“',
        21: 'Jener hingegen sprach über den Tempel seines Leibes.',
        22: 'Als er dann von den Toten auferweckt worden war, erinnerten sich seine Jünger, dass er dies gesagt hatte, und sie glaubten der Schrift und dem Wort, das Jesus gesagt hatte.',
        23: 'Als er nun während des Passa in Jerusalem auf dem Fest war, glaubten viele an seinen Namen, weil sie seine Zeichen sahen, die er tat;',
        24: 'Jesus selbst aber vertraute sich ihnen nicht an, weil er sie alle kannte',
        25: 'und weil er es nicht nötig hatte, dass jemand Zeugnis ablegt über den Menschen; denn er selbst erkannte, was im Menschen war.',
    },
    3: {
        1: 'Es gab aber einen Mann von den Pharisäern, Nikodemus [war] sein Name, ein Vorsteher der Judäer;',
        2: 'dieser kam eines Nachts zu ihm, und er sagte zu ihm: „Rabbi, wir wissen, dass du als Lehrer von Gott gekommen bist; denn niemand kann diese Zeichen tun, die du tust, es sei denn, Gott ist mit ihm.“',
        3: 'Jesus antwortete und sagte zu ihm: „Amen, amen, ich sage dir: Wenn jemand nicht von oben geboren wird, kann er das Reich Gottes nicht sehen.“',
        4: 'Nikodemus sagt zu ihm: „Wie kann ein Mensch geboren werden, wenn er alt ist? Kann er etwa ein zweites [Mal] in den Bauch seiner Mutter hineinschlüpfen und geboren werden?“',
        5: 'Jesus antwortete: „Amen, amen, ich sage dir: Wenn jemand nicht aus Wasser und Geist geboren wird, kann er nicht in das Reich Gottes eingehen.',
        6: 'Was aus dem Fleisch geboren ist, ist Fleisch, und was aus dem Geist geboren ist, ist Geist.',
        7: 'Wundere dich nicht, dass ich dir gesagt habe: Ihr müsst von oben geboren werden.',
        8: 'Der Wind weht, wo er will, und du hörst sein Rauschen, doch du weißt nicht, woher er kommt und wohin er geht; so ist jeder, der aus dem Geist geboren ist.“',
        9: 'Nikodemus antwortete und sagte zu ihm: „Wie kann das geschehen?“',
        10: 'Jesus antwortete und sagte zu ihm: „Du bist der Lehrer Israels und verstehst das nicht?',
        11: 'Amen, amen, ich sage dir: Was wir wissen, davon reden wir, und was wir gesehen haben, bezeugen wir; und doch nehmt ihr unser Zeugnis nicht an.',
        12: 'Wenn ich von den irdischen [Dingen] zu euch gesprochen habe und ihr es nicht glaubt, wie werdet ihr glauben, wenn ich von den himmlischen [Dingen] zu euch spreche?',
        13: 'Und niemand ist in den Himmel hinaufgestiegen außer dem, der vom Himmel herabgestiegen ist: der Menschensohn.',
        14: 'Und wie Mose die Schlange erhöht hat in der Wüste, so muss der Menschensohn erhöht werden,',
        15: 'damit jeder, der an ihn glaubt, ewiges Leben hat.“',
        16: '„Gott hat die Welt nämlich so sehr geliebt, dass er [seinen] einzigen Sohn gegeben hat, damit jeder, der an ihn glaubt, nicht verloren geht, sondern ewiges Leben hat.',
        17: 'Gott hat [seinen] Sohn nämlich nicht in die Welt gesandt, damit er die Welt richtet, sondern damit die Welt durch ihn gerettet wird.',
        18: 'Wer an ihn glaubt, wird nicht gerichtet; aber wer nicht glaubt, ist schon gerichtet, weil er nicht an den Namen des einzigen Sohnes Gottes geglaubt hat.',
        19: 'Dies aber ist das Gericht: Das Licht ist in die Welt gekommen, und die Menschen haben die Finsternis mehr geliebt als das Licht; denn ihre Taten waren böse.',
        20: 'Denn jeder, der Schlechtes tut, hasst das Licht, und er kommt nicht zum Licht, damit seine Taten nicht aufgedeckt werden.',
        21: 'Aber wer die Wahrheit tut, kommt zum Licht, damit seine Taten sichtbar werden, dass sie in Gott getan sind.“',
        22: 'Danach kam Jesus samt seinen Jüngern ins Land Judäa, und für gewöhnlich hielt er sich dort mit ihnen auf und taufte.',
        23: 'Es war aber auch Johannes da und taufte in Änon, nahe bei Salim, weil es dort viel Wasser gab, und sie begaben sich hin und ließen sich taufen;',
        24: 'Johannes war nämlich noch nicht ins Gefängnis geworfen worden.',
        25: 'Darauf entstand eine Streitfrage zwischen den Jüngern des Johannes und einem Judäer bezüglich der [rituellen] Reinigung.',
        26: 'Und sie kamen zu Johannes, und sie sagten zu ihm: „Rabbi, der bei dir war jenseits des Jordans [und] für den du Zeugnis abgelegt hast, siehe!, dieser tauft, und alle kommen zu ihm.“',
        27: 'Johannes antwortete und sagte: „Der Mensch kann nichts nehmen, auch nicht eins, es sei denn, es ist ihm vom Himmel gegeben.',
        28: 'Ihr selbst seid meine Zeugen, dass ich gesagt habe: ‚Ich bin nicht der Gesalbte‘, sondern: ‚Ich bin vor ihm her gesandt.‘“',
        29: 'Wer die Braut hat, ist der Bräutigam; aber der Freund des Bräutigams, der dasteht und ihm zuhört, ‹freut sich sehr› über die Stimme des Bräutigams. Diese meine Freude ist nun erfüllt.',
        30: 'Jener muss wachsen, ich hingegen geringer werden.',
        31: 'Der von oben her kommt, ist über allem; der von der Erde ist, ist von der Erde und redet von der Erde her; der vom Himmel kommt, ist über allem.',
        32: 'Was er gesehen und gehört hat, das bezeugt er, und doch nimmt keiner sein Zeugnis an.',
        33: 'Wer sein Zeugnis angenommen hat, hat besiegelt, dass Gott wahrhaftig ist.',
        34: 'Denn er, den Gott ausgesandt hat, redet die Worte Gottes; er gibt den Geist nämlich nicht in Maßen.',
        35: 'Der Vater liebt den Sohn, und alles hat er in seine Hand gegeben.',
        36: 'Wer an den Sohn glaubt, hat ewiges Leben; aber wer dem Sohn nicht gehorsam ist, wird [dieses] Leben nicht sehen, sondern der Zorn Gottes bleibt auf ihm.“',
    },
    4: {
        1: 'Als nun Jesus erfuhr, dass die Pharisäer gehört hatten, dass Jesus mehr Jünger machte und taufte als Johannes –',
        2: 'obwohl Jesus selbst nicht taufte, sondern seine Jünger –,',
        3: 'da verließ er Judäa, und er ging wieder nach Galiläa.',
        4: 'Er musste aber durch Samaria hindurchreisen.',
        5: 'Er kommt also in eine Stadt Samarias, die Sychar heißt, ganz in der Nähe des Grundstücks, das Jakob seinem Sohn Josef gegeben hatte.',
        6: 'Nun war dort eine Quelle Jakobs. Da Jesus also müde war von der Reise, blieb er einfach an der Quelle sitzen; es war etwa die sechste Stunde.',
        7: 'Eine Frau aus Samaria kommt, um Wasser zu schöpfen. Jesus sagt zu ihr: „Gib mir zu trinken!“',
        8: '(Denn seine Jünger waren in die Stadt gegangen, um Essen zu kaufen.)',
        9: 'Darauf sagt die samaritische Frau zu ihm: „Wieso bittest du, der du ein Judäer bist, von mir zu trinken, die ich eine samaritische Frau bin? Judäer verkehren nämlich nicht mit Samaritern.“',
        10: 'Jesus antwortete und sagte zu ihr: „Wenn du die Gabe Gottes erkannt hättest und wer es ist, der zu dir sagt: ‚Gib mir zu trinken!‘, dann hättest du ihn gebeten und er hätte dir frisches Wasser gegeben.“',
        11: 'Die Frau sagt zu ihm: „Herr, du hast nicht mal einen Eimer, und der Brunnen ist tief. Woher hast du also das frische Wasser?',
        12: 'Bist du etwa größer als unser Vater Jakob, der uns den Brunnen gegeben und selbst aus ihm getrunken hat, samt seinen Söhnen und seinem Vieh?“',
        13: 'Jesus antwortete und sagte zu ihr: „Jeder, der von diesem Wasser trinkt, wird wieder Durst haben.',
        14: 'Aber wer auch immer von dem Wasser trinkt, das ich ihm geben werde, wird gewiss nicht Durst haben bis in Ewigkeit, sondern das Wasser, das ich ihm geben werde, wird in ihm zu einer Quelle von Wasser werden, das bis ins ewige Leben sprudelt.“',
        15: 'Die Frau sagt zu ihm: „Herr, gib mir dieses Wasser, damit ich keinen Durst [mehr] habe und nicht [mehr] hierher kommen muss, um zu schöpfen.“',
        16: 'Er sagt zu ihr: „Geh, rufe deinen Mann und komm [wieder] hierher!“',
        17: 'Die Frau antwortete und sagte zu ihm: „Ich habe keinen Mann.“Jesus sagt zu ihr: „Du hast zu Recht gesagt: ‚Ich habe keinen Mann.‘',
        18: 'Denn fünf Männer hast du gehabt, und der, den du jetzt hast, ist nicht dein Mann; das hast du ganz recht gesagt.“',
        19: 'Die Frau sagt zu ihm: „Herr, ich sehe, dass du ein Prophet bist.',
        20: 'Unsere Vorfahren haben auf diesem Berg angebetet; und doch sagt ihr, dass in Jerusalem der Ort sei, wo man anbeten soll.‘“',
        21: 'Jesus sagt zu ihr: „Glaube mir, Frau: Es kommt eine Stunde, in der ihr den Vater weder auf diesem Berg noch in Jerusalem anbeten werdet.',
        22: 'Ihr betet an, was ihr nicht kennt; wir beten an, was wir kennen, weil das Heil von den Judäern stammt.',
        23: 'Doch es kommt eine Stunde (und sie ist jetzt da), in der die wahren Anbeter den Vater in Geist und Wahrheit anbeten werden; denn auch der Vater sucht solche, die ihn anbeten.',
        24: 'Gott [ist] Geist, und die ihn anbeten, müssen in Geist und Wahrheit anbeten.“',
        25: 'Die Frau sagt zu ihm: „Ich weiß, dass der Messias kommt, der sogenannte ‚Gesalbte‘; wenn jener kommt, wird er uns alles verkünden.“',
        26: 'Jesus sagt zu ihr: „Ich bin es – der zu dir redet!“',
        27: 'Und in diesem [Moment] kamen seine Jünger, und sie wunderten sich, dass er mit einer Frau redete; dennoch sagte keiner: „Was suchst du?“, oder: „Warum redest du mit ihr?“',
        28: 'Darauf ließ die Frau ihren Wasserkrug [stehen], und sie ging los in die Stadt, und sie sagt zu den Leuten:',
        29: '„Kommt, seht den Menschen, der mir alles gesagt hat, was ich getan habe; ist dieser etwa der Gesalbte?“',
        30: 'Sie kamen aus der Stadt heraus, und sie gingen zu ihm.',
        31: 'In der Zwischenzeit baten ihn die Jünger und sagten: „Rabbi, iss!“',
        32: 'Er aber sagte zu ihnen: „Ich habe eine Speise zu essen, von der ihr nicht wisst.“',
        33: 'Darauf sagten die Jünger zueinander: „Hat ihm etwa jemand zu essen gebracht?“',
        34: 'Jesus sagt zu ihnen: „Meine Speise ist, dass ich den Willen dessen tue, der mich gesandt hat, und sein Werk vollende.',
        35: 'Sagt ihr nicht: ‚Es sind noch vier Monate, dann kommt die Ernte‘? Siehe!, ich sage euch: Hebt eure Augen auf und schaut die Felder an, dass sie schon weiß sind zur Ernte!',
        36: 'Wer erntet, erhält Lohn und sammelt Frucht für das ewige Leben, sodass sich [beide] – der sät und der erntet – gemeinsam freuen.',
        37: 'Denn in diesem [Punkt] ist das Sprichwort wahr: ‚Einer ist es, der sät, und ein anderer, der erntet.‘',
        38: 'Ich habe euch ausgesandt, um zu ernten, woran ihr nicht gearbeitet habt; andere haben gearbeitet, und ihr seid in ihre Arbeit eingetreten.“',
        39: 'Von jener Stadt aber glaubten viele der Samariter an ihn wegen des Wortes der Frau, die bezeugte: „Er hat mir alles gesagt, was ich getan habe!“',
        40: 'Als nun die Samariter zu ihm kamen, baten sie ihn, bei ihnen zu bleiben; und er blieb dort zwei Tage.',
        41: 'Und viel mehr glaubten wegen seines Wortes,',
        42: 'und zu der Frau sagten sie: „Wir glauben nicht länger wegen deines Redens, denn wir selbst haben [ihn] gehört, und wir wissen, dass er tatsächlich der Retter der Welt ist.“',
        43: 'Nach den zwei Tagen aber ging er von dort weg nach Galiläa;',
        44: 'denn Jesus selbst hatte bezeugt, dass ein Prophet in der eigenen Heimat kein Ansehen hat.',
        45: 'Als er dann nach Galiläa kam, nahmen ihn die Galiläer auf, weil sie alles gesehen hatten, was er in Jerusalem bei dem Fest getan hatte, denn auch sie waren zu dem Fest gekommen.',
        46: 'Er kam dann wieder nach Kana in Galiläa, wo er das Wasser zu Wein gemacht hatte. Und es war in Kafarnaum ein königlicher [Beamter], dessen Sohn krank war.',
        47: 'Als dieser hörte, dass Jesus von Judäa nach Galiläa kommt, ging er zu ihm und bat wiederholt, dass er hinabsteige und seinen Sohn heile, denn er drohte zu sterben.',
        48: 'Da sagte Jesus zu ihm: „Wenn ihr keine Zeichen und Wunder seht, dann glaubt ihr einfach nicht.“',
        49: 'Der königliche [Beamte] sagt zu ihm: „Herr, steig hinab, bevor mein Kind stirbt!“',
        50: 'Jesus sagt zu ihm: „Geh, dein Sohn lebt!“Der Mann glaubte dem Wort, das Jesus ihm gesagt hatte, und er ging.',
        51: 'Aber schon während er hinabstieg, kamen ihm seine Knechte entgegen und sagten, dass sein Junge lebt.',
        52: 'Darauf erkundigte er sich bei ihnen nach der Stunde, in der ‹es ihm besser ging›. Darauf sagten sie zu ihm: „Gestern zur siebten Stunde hat ihn das Fieber verlassen.“',
        53: 'Da merkte der Vater, dass [es] in jener Stunde [gewesen war], in der Jesus zu ihm gesagt hatte: „Dein Sohn lebt!“, und er glaubte, er und sein ganzes Haus.',
        54: 'Das aber tat Jesus wieder (als zweites Zeichen), als er von Judäa nach Galiläa kam.',
    },
    5: {
        1: 'Danach war ein Fest der Judäer, und Jesus stieg hinauf nach Jerusalem.',
        2: 'Nun gibt es in Jerusalem bei dem Schaftor einen Teich, der auf Hebräisch Betzata genannt wird [und] fünf Säulenhallen hat.',
        3: 'In diesen lag für gewöhnlich eine Menge von Kranken: Blinde, Lahme, Ausgezehrte.',
        5: 'Dort war nun ein Mann, der achtunddreißig Jahre mit seiner Krankheit zugebracht hatte.',
        6: 'Als Jesus ihn daliegen sah und erfuhr, dass er schon eine lange Zeit so zugebracht hatte, sagt er zu ihm: „Willst du gesund werden?“',
        7: 'Der Kranke antwortete ihm: „Herr, ich habe keinen Menschen, um mich in den Teich zu tun, sobald das Wasser aufgewühlt wird. Und während ich gehe, steigt ein anderer vor mir hinunter.“',
        8: 'Jesus sagt zu ihm: „Steh auf, nimm deine Matte und geh umher!“',
        9: 'Und sofort wurde der Mann gesund, und er nahm seine Matte und ging umher. Es war aber Sabbat an jenem Tag.',
        10: 'Also sagten die Judäer zu dem Geheilten: „Es ist Sabbat, und es ist dir nicht erlaubt, deine Matte zu tragen.“',
        11: 'Er aber antwortete ihnen: „Der mich gesund gemacht hat, der hat zu mir gesagt: ‚Nimm deine Matte und geh umher!‘“',
        12: 'Sie fragten ihn: „Wer ist der Mann, der zu dir gesagt hat: ‚Nimm sie und geh umher‘?“',
        13: 'Der Geheilte aber wusste nicht, wer es war, denn Jesus hatte sich zurückgezogen, weil eine Menschenmenge an dem Ort war.',
        14: 'Danach trifft Jesus ihn im Tempel, und er sagte zu ihm: „Siehe!, du bist gesund geworden; sündige nicht mehr, damit dir nicht etwas Schlimmeres zustößt!“',
        15: 'Der Mann ging fort, und er berichtete den Judäern, dass Jesus es war, der ihn gesund gemacht hatte.',
        16: 'Und deshalb verfolgten die Judäer Jesus, weil er dies an einem Sabbat tat.',
        17: 'Jesus aber antwortete ihnen: „Mein Vater wirkt bis jetzt, [und] auch ich wirke.“',
        18: 'Deshalb versuchten die Judäer nun umso mehr, ihn zu töten, weil er nicht nur den Sabbat brach, sondern Gott auch seinen Vater nannte und dabei sich selbst Gott gleich machte.',
        19: 'Also antwortete Jesus, und er sagte zu ihnen: „Amen, amen, ich sage euch: Von sich selbst aus kann der Sohn gar nichts tun, außer, was er den Vater tun sieht. Denn was auch immer jener tut, das tut genauso auch der Sohn.',
        20: 'Denn der Vater liebt den Sohn, und er zeigt ihm alles, was er selbst tut, und er wird ihm größere Werke als diese zeigen, sodass ihr staunen werdet.',
        21: 'Denn wie der Vater die Toten auferweckt und lebendig macht, so macht auch der Sohn lebendig, wen er will.',
        22: 'Denn auch nicht einen richtet der Vater, sondern das ganze Gericht hat er dem Sohn gegeben,',
        23: 'damit alle den Sohn ehren, wie sie den Vater ehren. Wer den Sohn nicht ehrt, ehrt den Vater nicht, der ihn geschickt hat.',
        24: 'Amen, amen, ich sage euch: Wer mein Wort hört und dem glaubt, der mich geschickt hat, der hat ewiges Leben und kommt nicht ins Gericht, sondern er ist aus dem Tod ins Leben übergegangen.',
        25: 'Amen, amen, ich sage euch: Es kommt eine Stunde (und sie ist jetzt da), in der die Toten die Stimme des Sohnes Gottes hören werden, und die sie gehört haben, werden leben.',
        26: 'Denn wie der Vater Leben in sich selbst hat, so hat er es auch dem Sohn ermöglicht, Leben in sich selbst zu haben.',
        27: 'Und er hat ihm Macht gegeben, Gericht zu halten, weil er der Menschensohn ist.',
        28: 'Wundert euch nicht darüber, dass eine Stunde kommt, in der alle, die in den Gräbern [sind], seine Stimme hören werden,',
        29: 'und es werden herauskommen, die Gutes getan haben, zur Auferstehung des Lebens, und die Schlechtes getan haben, zur Auferstehung des Gerichts.“',
        30: '„Ich kann gar nichts von mir selbst aus tun; wie ich höre, so richte ich, und mein Gericht ist gerecht, weil ich nicht meinen Willen suche, sondern den Willen dessen, der mich geschickt hat.',
        31: 'Wenn ich Zeugnis ablege über mich selbst, dann ist mein Zeugnis nicht zuverlässig;',
        32: 'ein anderer ist es, der Zeugnis ablegt über mich, und ich weiß, dass das Zeugnis zuverlässig ist, das er ablegt über mich.',
        33: 'Ihr habt [Leute] zu Johannes gesandt, und er hat für die Wahrheit Zeugnis abgelegt;',
        34: 'ich aber nehme das Zeugnis von einem Menschen nicht an, sondern dies sage ich, damit ihr gerettet werdet.',
        35: 'Jener war die Lampe, die brennt und scheint, ihr hingegen wolltet für einen Moment fröhlich sein in ihrem Licht.',
        36: 'Ich aber habe das Zeugnis, das größer [ist] als das von Johannes; denn die Werke, die der Vater mir gegeben hat, damit ich sie vollende … die Werke selbst, die ich tue, legen Zeugnis ab über mich, dass der Vater mich gesandt hat.',
        37: 'Und der Vater, der mich geschickt hat, er hat Zeugnis abgelegt über mich. Weder habt ihr seine Stimme jemals gehört, noch habt ihr seine Gestalt gesehen,',
        38: 'und sein Wort habt ihr nicht bleibend in euch, weil ihr dem nicht glaubt, den jener gesandt hat.',
        39: 'Ihr erforscht die Schriften, weil ihr meint, in ihnen ewiges Leben zu haben; und sie sind es, die Zeugnis ablegen über mich;',
        40: 'und doch wollt ihr nicht zu mir kommen, um Leben zu haben.',
        41: 'Ehre von Menschen nehme ich keine,',
        42: 'doch ich habe euch erkannt, dass ihr die Liebe Gottes nicht in euch habt.',
        43: 'Ich bin gekommen im Namen meines Vaters, und ihr nehmt mich nicht an; wenn ein anderer in seinem eigenen Namen kommt, werdet ihr jenen annehmen.',
        44: 'Wie könnt ihr glauben, die ihr Ehre voneinander annehmt, aber die Ehre, die von dem alleinigen Gott [stammt], sucht ihr nicht?!',
        45: 'Meint nicht, dass ich euch anklagen werde beim Vater; der euch anklagt, ist Mose, auf den ihr gehofft habt.',
        46: 'Denn wenn ihr Mose glauben würdet, dann würdet ihr mir glauben; denn über mich hat jener geschrieben.',
        47: 'Aber wenn ihr seinen Schriften nicht glaubt, wie werdet ihr meinen Worten glauben?“',
    },
    6: {
        1: 'Danach fuhr Jesus ans gegenüberliegende [Ufer] des Meeres von Galiläa [beziehungsweise] von Tiberias.',
        2: 'Es folgte ihm aber ständig eine große Menschenmenge, weil sie die Zeichen sahen, die er an den Kranken tat.',
        3: 'Da ging Jesus auf den Berg hinauf, und dort setzte er sich mit seinen Jüngern.',
        4: 'Es war aber das Passa nahe, das Fest der Judäer.',
        5: 'Als nun Jesus die Augen aufhob und sah, dass eine große Menschenmenge zu ihm kommt, sagt er zu Philippus: „Woher sollen wir Brote kaufen, damit diese [Leute] essen können?“',
        6: 'Dies sagte er aber, um ihn auf die Probe zu stellen; denn er selbst wusste, was er zu tun gedachte.',
        7: 'Philippus antwortete ihm: „Brote für zweihundert Denare reichen nicht für sie, damit jeder ein klein wenig bekommt.“',
        8: 'Einer von seinen Jüngern – Andreas, der Bruder von Simon Petrus – sagt zu ihm:',
        9: '„Es ist ein kleiner Junge hier, der hat fünf Gerstenbrote und zwei Fische … doch was ist das für so viele?“',
        10: 'Jesus sagte: „Sorgt dafür, dass die Leute lagern!“Nun gab es viel Gras an dem Ort. Die Männer lagerten also, etwa fünftausend an der Zahl.',
        11: 'Dann nahm Jesus die Brote, und nachdem er gedankt hatte, verteilte er sie an die Lagernden, genauso auch von den Fischen so viel sie wollten.',
        12: 'Als sie nun gesättigt waren, sagt er zu seinen Jüngern: „Sammelt die übrig gebliebenen Brocken, damit nichts verdirbt!“',
        13: 'Da sammelten und füllten sie von den fünf Gerstenbroten zwölf Körbe an Brocken, die denen, die gegessen hatten, übrig geblieben waren.',
        14: 'Als nun die Menschen sahen, was für ein Zeichen er getan hatte, sagten sie: „Dieser [Mann] ist tatsächlich der Prophet, der in die Welt kommt.“',
        15: 'Da nun Jesus erkannte, dass sie kommen und ihn ergreifen wollten, um ihn zum König zu machen, zog er sich wieder auf den Berg zurück, er allein.',
        16: 'Als es nun Abend wurde, stiegen seine Jünger hinab zum Meer,',
        17: 'und nachdem sie in ein Boot gestiegen waren, fuhren sie ans gegenüberliegende [Ufer] des Meeres nach Kafarnaum. Und es war schon dunkel geworden, und Jesus war noch nicht zu ihnen gekommen,',
        18: 'Und das Meer war aufgewühlt, weil ein starker Wind wehte.',
        19: 'Als sie nun etwa fünfundzwanzig oder dreißig Stadien [weit] gekommen waren, sehen sie Jesus auf dem Meer umhergehen und nahe an das Boot herankommen, und sie fürchteten sich.',
        20: 'Er aber sagt zu ihnen: „Ich bin [es]; fürchtet euch nicht!“',
        21: 'Da wollten sie ihn in das Boot nehmen, und sofort erreichte das Boot das Land, zu dem sie unterwegs waren.',
        22: 'Am nächsten [Tag] sah die Menschenmenge, die am gegenüberliegenden [Ufer] des Meeres stand, dass dort kein anderes Boot war außer einem und dass Jesus nicht zusammen mit seinen Jüngern in das Boot gestiegen war, sondern seine Jünger allein losgefahren waren;',
        23: 'es kamen weitere kleine Boote aus Tiberias nahe an den Ort, wo sie das Brot gegessen hatten, nachdem der Herr gedankt hatte.',
        24: 'Als nun die Menschenmenge sah, dass weder Jesus noch seine Jünger dort waren, stiegen sie in die Boote, und sie fuhren nach Kafarnaum, um Jesus zu suchen.',
        25: 'Und als sie ihn am gegenüberliegenden [Ufer] des Meeres gefunden hatten, sagten sie zu ihm: „Rabbi, wann bist du hier eingetroffen?“',
        26: 'Jesus antwortete ihnen und sagte: „Amen, amen, ich sage euch: Ihr sucht mich nicht, weil ihr Zeichen gesehen habt, sondern weil ihr von den Broten gegessen habt und satt geworden seid.',
        27: 'Beschafft euch nicht die Speise, die verdirbt, sondern die Speise, die bis ins ewige Leben bleibt, das der Menschensohn euch geben wird; denn ihn hat der Vater, hat Gott bestätigt.“',
        28: 'Da sagten sie zu ihm: „Was sollen wir tun, um die Werke Gottes zu wirken?“',
        29: 'Jesus antwortete und sagte zu ihnen: „Dies ist das Werk Gottes: dass ihr an den glaubt, den jener gesandt hat.“',
        30: 'Da sagten sie zu ihm: „Was tust du denn als Zeichen, damit wir es sehen und dir glauben? Was wirkst du?',
        31: 'Unsere Vorfahren haben das Manna gegessen in der Wüste, wie geschrieben steht: ‚Brot vom Himmel gab er ihnen zu essen.‘“',
        32: 'Da sagte Jesus zu ihnen: „Amen, amen, ich sage euch: Nicht Mose hat euch das Brot vom Himmel gegeben, sondern mein Vater gibt euch das wahre Brot vom Himmel.',
        33: 'Denn das Brot Gottes ist derjenige, der vom Himmel herabkommt und der Welt Leben gibt.“',
        34: 'Also sagten sie zu ihm: „Herr, gib uns immer dieses Brot!“',
        35: 'Jesus sagte zu ihnen: „Ich bin das Brot des Lebens! Wer zu mir kommt, soll gewiss nicht hungern, und wer an mich glaubt, wird gewiss nie mehr Durst haben.',
        36: 'Doch ich habe euch gesagt, dass ihr mich sogar gesehen habt und doch nicht glaubt.',
        37: 'Alles, was mir der Vater gibt, wird zu mir kommen, und den, der zu mir kommt, stoße ich gewiss nicht hinaus,',
        38: 'weil ich nicht vom Himmel herabgekommen bin, um meinen Willen zu tun, sondern den Willen dessen, der mich geschickt hat.',
        39: 'Dies aber ist der Wille dessen, der mich geschickt hat: dass alles, was er mir gegeben hat … dass ich nichts davon verliere, sondern es auferstehen lasse am letzten Tag.',
        40: 'Denn dies ist der Wille meines Vaters: dass jeder, der den Sohn sieht und an ihn glaubt, ewiges Leben hat und ich ihn auferstehen lassen werde am letzten Tag.“',
        41: 'Da fingen die Judäer an, über ihn zu murren, weil er gesagt hatte: „Ich bin das Brot, das vom Himmel herabgekommen ist“,',
        42: 'und sie sagten: „Ist dieser [Mann] nicht Jesus, der Sohn von Josef, dessen Vater und Mutter wir kennen? Mit welchem Recht sagt er jetzt: ‚Ich bin vom Himmel herabgekommen‘?“',
        43: 'Jesus antwortete und sagte zu ihnen: „Murrt nicht miteinander!',
        44: 'Niemand kann zu mir kommen, es sei denn, der Vater, der mich geschickt hat, zieht ihn, und ich werde ihn auferstehen lassen am letzten Tag.',
        45: 'Es steht geschrieben in den Propheten: ‚Und sie werden alle von Gott gelehrt sein!‘Jeder, der vom Vater gehört und gelernt hat, kommt zu mir.',
        46: '[Das bedeutet] nicht, dass jemand den Vater gesehen hat, außer dem, der von Gott ist, der hat den Vater gesehen.',
        47: 'Amen, amen, ich sage euch: Wer glaubt, hat ewiges Leben.',
        48: 'Ich bin das Brot des Lebens!',
        49: 'Eure Vorfahren haben in der Wüste das Manna gegessen und sind gestorben.',
        50: 'Dies ist das Brot, das vom Himmel herabkommt, damit man davon isst und nicht stirbt.',
        51: 'Ich bin das lebendige Brot, das vom Himmel herabgekommen ist! Wenn jemand von diesem Brot isst, dann wird er ‹für immer› leben, und das Brot, das ich geben werde, ist mein Fleisch für das Leben der Welt.“',
        52: 'Nun fingen die Judäer an, miteinander zu streiten und zu sagen: „Wie kann er uns sein Fleisch zu essen geben?“',
        53: 'Da sagte Jesus zu ihnen: „Amen, amen, ich sage euch: Wenn ihr das Fleisch des Menschensohns nicht esst und sein Blut nicht trinkt, dann habt ihr in euch selbst kein Leben.',
        54: 'Wer mein Fleisch isst und mein Blut trinkt, hat ewiges Leben, und ich werde ihn auferstehen lassen am letzten Tag.',
        55: 'Denn mein Fleisch ist wahre Speise, und mein Blut ist wahrer Trank.',
        56: 'Wer mein Fleisch isst und mein Blut trinkt, bleibt in mir und ich in ihm.',
        57: 'Wie mich der lebendige Vater gesandt hat und ich um des Vaters willen lebe, so auch derjenige, der mich isst … auch er wird um meinetwillen leben.',
        58: 'Dies ist das Brot, das vom Himmel herabgekommen ist (nicht wie [eure] Vorfahren aßen und starben). Wer dieses Brot ist, wird ‹für immer› leben.“',
        59: 'Diese [Dinge] sagte er, als er in einer Synagoge in Kafarnaum lehrte.',
        60: 'Nun sagten viele von seinen Jüngern, die zugehört hatten: „Diese Rede ist hart! Wer kann es hören?“',
        61: 'Da nun Jesus bei sich selbst wusste, dass seine Jünger darüber murrten, sagte er zu ihnen: „Das gibt euch Anstoß?',
        62: '[Was ist], wenn ihr nun den Menschensohn [dorthin] aufsteigen seht, wo er vorher war?',
        63: 'Der Geist ist es, der lebendig macht, das Fleisch nützt gar nichts! Die Worte, die ich zu euch geredet habe, sind Geist und sind Leben.',
        64: 'Doch es gibt einige unter euch, die nicht glauben.“Jesus wusste nämlich von Anfang an, wer diejenigen sind, die nicht glauben, und wer derjenige ist, der ihn verraten würde.',
        65: 'Und er sagte: „Deshalb habe ich euch gesagt, dass niemand zu mir kommen kann, es sei denn, es ist ihm vom Vater gegeben.“',
        66: 'Von da an gingen viele seiner Jünger zurück, und sie zogen nicht mehr mit ihm umher.',
        67: 'Also sagte Jesus zu den zwölf: „Wollt nicht auch ihr gehen?“',
        68: 'Simon Petrus antwortete ihm: „Herr, zu wem sollen wir gehen? Worte des ewigen Lebens hast du.',
        69: 'Und wir glauben fest und haben erkannt, dass du der Heilige Gottes bist.“',
        70: 'Jesus antwortete ihnen: „Habe nicht ich euch zwölf ausgewählt? Und doch ist einer von euch ein Teufel.“',
        71: 'Er redete aber von Judas, [dem Sohn] von Simon Iskariot; denn dieser würde ihn verraten, einer von den zwölf.',
    },
    7: {
        1: 'Und danach zog Jesus in Galiläa umher; er wollte nämlich nicht in Judäa umherziehen, weil die Judäer ihn zu töten versuchten.',
        2: 'Nun war das Fest der Judäer nahe, das Laubhüttenfest.',
        3: 'Also sagten seine Geschwister zu ihm: „Zieh von hier weiter und geh nach Judäa, damit auch deine Jünger deine Werke sehen, die du tust.',
        4: 'Denn niemand tut etwas im Verborgenen und versucht doch, selbst in der Öffentlichkeit zu stehen. Wenn du diese [Werke] tust, dann gib dich selbst der Welt zu erkennen!“',
        5: '(Denn auch seine Geschwister glaubten nicht an ihn.)',
        6: 'Da sagt Jesus zu ihnen: „Meine Zeit ist noch nicht da, aber eure Zeit ist immer bereit.',
        7: 'Euch kann die Welt nicht hassen, mich aber hasst sie, weil ich über sie bezeuge, dass ihre Werke böse sind.',
        8: 'Steigt ihr hinauf zu dem Fest! Ich steige nicht hinauf zu diesem Fest, weil meine Zeit noch nicht erfüllt ist.“',
        9: 'Nachdem er dies nun gesagt hatte, blieb er selbst in Galiläa.',
        10: 'Als aber seine Geschwister hinaufgestiegen waren zu dem Fest, da stieg auch er hinauf, nicht öffentlich, sondern wie im Verborgenen.',
        11: 'Da suchten ihn die Judäer auf dem Fest und sagten: „Wo ist er?“',
        12: 'Und das Gemurmel über ihn war groß unter den Menschenmengen; die einen sagten: „Er ist gut“, andere wiederum sagten: „Nein, sondern er verführt die Menschenmenge.“',
        13: 'Dennoch redete niemand öffentlich über ihn, aus Angst vor den Judäern.',
        14: 'Als nun das Fest bereits halb vorüber war, stieg Jesus hinauf zum Tempel und lehrte.',
        15: 'Da staunten die Judäer und sagten: „Wie kennt dieser [Mann] die Schriften, obwohl er nicht studiert hat?“',
        16: 'Da antwortete ihnen Jesus und sagte: „Meine Lehre ist nicht meine, sondern dessen, der mich geschickt hat.',
        17: 'Wenn jemand seinen Willen tun will, dann wird er bezüglich der Lehre erkennen, ob sie von Gott ist oder ich von mir selbst aus rede.',
        18: 'Wer von sich selbst aus redet, sucht die eigene Ehre; aber wer die Ehre dessen sucht, der ihn geschickt hat, der ist zuverlässig, und es gibt keine Ungerechtigkeit in ihm.',
        19: 'Hat nicht Mose euch das Gesetz gegeben? Und doch tut keiner von euch das Gesetz. Warum versucht ihr, mich zu töten?“',
        20: 'Die Menschenmenge antwortete: „Du hast einen Dämon! Wer versucht, dich zu töten?“',
        21: 'Jesus antwortete und sagte zu ihnen: „Ein einziges Werk habe ich getan, und ihr alle staunt.',
        22: 'Deshalb hat euch Mose die Beschneidung gegeben – nicht, dass sie von Mose stammt, sondern von den Vorfahren –: Auch am Sabbat beschneidet ihr einen Menschen.',
        23: 'Wenn ein Mensch am Sabbat eine Beschneidung erhält, damit das Gesetz des Mose nicht missachtet wird, [warum] nehmt ihr es mir übel, dass ich am Sabbat einen ‹Menschen am ganzen Körper› gesund gemacht habe?',
        24: 'Urteilt nicht nach dem Anschein, sondern fällt das gerechte Urteil!“',
        25: 'Nun sagten einige von den Bewohnern Jerusalems: „Ist er nicht der, den sie zu töten versuchen?',
        26: 'Und siehe!, er spricht in der Öffentlichkeit, und sie erwidern ihm nichts! Haben die Vorsteher etwa tatsächlich erkannt, dass dieser [Mann] der Gesalbte ist?',
        27: 'Wir wissen jedoch, woher dieser [Mann] stammt. Aber wenn der Gesalbte kommt, erfährt niemand, woher er stammt.“',
        28: 'Da rief Jesus, als er im Tempel lehrte und sprach: „Und mich kennt ihr und ihr wisst, woher ich stamme. Und ich bin nicht von mir selbst aus gekommen, sondern der mich geschickt hat, ist wahrhaftig – der, den ihr nicht kennt!',
        29: 'Ich kenne ihn, weil ich von ihm stamme, und er hat mich gesandt.“',
        30: 'Darauf versuchten sie, ihn zu verhaften, aber keiner legte die Hand an ihn, weil seine Stunde noch nicht gekommen war.',
        31: 'Viele aus der Menschenmenge aber glaubten an ihn, und sie sagten: „Wird der Gesalbte, wenn er kommt, etwa größere Zeichen tun, als dieser getan hat?“',
        32: 'Die Pharisäer hörten die Menschenmenge diese [Dinge] über ihn murmeln; und die Oberpriester und die Pharisäer sandten Tempeldiener, um ihn zu verhaften.',
        33: 'Also sagte Jesus: „Noch eine kurze Zeit bin ich bei euch, dann gehe ich zu dem hin, der mich geschickt hat.',
        34: 'Ihr werdet mich suchen, aber ihr werdet mich nicht finden; und wo ich bin, da könnt ihr nicht hinkommen.“',
        35: 'Darauf sagten die Judäer zu sich: „Wohin sollte er gehen, dass wir ihn nicht finden werden? Will er etwa in die Zerstreuung der Griechen gehen und die Griechen lehren?',
        36: 'Was bedeutet dieses Wort, das er gesagt hat: ‚Ihr werdet mich suchen, aber ihr werdet mich nicht finden; und wo ich bin, da könnt ihr nicht hinkommen‘?“',
        37: 'Am letzten, großen Tag des Festes nun stellte sich Jesus hin, und er rief und sagte: „Wenn jemand Durst hat, dann soll er zu mir kommen und trinken!',
        38: 'Wer an mich glaubt, wie die Schrift gesagt hat, aus dessen Inneren werden Ströme lebendigen Wassers fließen.“',
        39: 'Dies aber sagte er über den Geist, den die erhalten würden, die an ihn glauben; der Geist war nämlich noch nicht da, weil Jesus auch noch nicht verherrlicht worden war.',
        40: 'Darauf sagten [einige] aus der Menschenmenge, die diese Worte gehört hatten: „Dieser [Mann] ist tatsächlich der Prophet!“',
        41: 'Andere sagten: „Dieser [Mann] ist der Gesalbte!“Manche sagten: „Kommt denn der Gesalbte etwa aus Galiläa?',
        42: 'Hat nicht die Schrift gesagt, dass der Gesalbte aus der Nachkommenschaft Davids und aus Betlehem – dem Dorf, wo David [her] war – kommt?“',
        43: 'Also entstand seinetwegen eine Auseinandersetzung in der Menschenmenge.',
        44: 'Einige aber von ihnen wollten ihn verhaften, doch niemand legte die Hände an ihn.',
        45: 'Also gingen die Tempeldiener zu den Oberpriestern und Pharisäern, und jene sagten zu ihnen: „Weshalb habt ihr ihn nicht hergebracht?“',
        46: 'Die Tempeldiener antworteten: „Noch nie hat ein Mensch so geredet!“',
        47: 'Darauf antworteten ihnen die Pharisäer: „Habt etwa auch ihr euch irreführen lassen?',
        48: 'Hat etwa irgendeiner von den Vorstehern an ihn geglaubt, oder von den Pharisäern?',
        49: 'Doch diese Menschenmenge, die das Gesetz nicht kennt, ist verflucht!“',
        50: 'Nikodemus, der zuvor zu ihm gekommen war [und] einer von ihnen war, sagt zu ihnen:',
        51: '„Richtet etwa unser Gesetz den Menschen, ohne dass man ihn zuerst angehört hat und in Erfahrung gebracht hat, was er getan hat?“',
        52: 'Sie antworteten und sagten zu ihm: „Bist etwa auch du aus Galiläa? Forsche nach und sieh [selbst]: Aus Galiläa wird kein Prophet erweckt!“',
        53: 'Dann ging ein jeder in sein Haus.',
    },
    8: {
        1: 'Jesus aber ging zum Ölberg.',
        2: 'Frühmorgens nun begab er sich wieder in den Tempel, und das ganze Volk kam zu ihm. Und er setzte sich und fing an, sie zu lehren.',
        3: 'Da bringen die Schriftgelehrten und Pharisäer eine Frau, die beim Ehebruch ertappt worden war, und sie stellen sie in die Mitte und',
        4: 'sagen zu ihm: „Lehrer, diese Frau ist auf frischer Tat ertappt worden, als sie die Ehe brach!',
        5: 'Im Gesetz aber hat uns Mose geboten, solche [Frauen] zu steinigen. Was sagst denn du?“',
        6: 'Das sagten sie aber, um ihn auf die Probe zu stellen, damit sie [einen Vorwand] hätten, ihn anzuklagen. Jesus aber bückte sich hinunter und fing an, mit dem Finger auf die Erde zu schreiben.',
        7: 'Während sie nun fortfuhren, ihn zu fragen, richtete er sich auf und sagte zu ihnen: „Wer von euch ohne Sünde [ist], soll als Erster einen Stein auf sie werfen!“',
        8: 'Dann bückte er sich wieder hinunter und schrieb auf die Erde.',
        9: 'Sie aber – als sie das hörten – gingen einer nach dem anderem weg, angefangen bei den Ältesten, und er wurde allein zurückgelassen, auch die Frau, die in der Mitte stand.',
        10: 'Als sich Jesus nun aufrichtete, sagte er zu ihr: „Frau, wo sind sie? Hat niemand dich verurteilt?“',
        11: 'Sie aber sagte: „Niemand, Herr.“Da sagte Jesus: „Auch ich verurteile dich nicht. Geh und sündige von jetzt an nicht mehr!“',
        12: 'Ein andermal redete Jesus dann zu ihnen und sagte: „Ich bin das Licht der Welt! Wer mir folgt, wird gewiss nicht in der Finsternis leben, sondern er wird das Licht des Lebens haben.“',
        13: 'Da sagten die Pharisäer zu ihm: „Du legst Zeugnis über dich selbst ab? Dein Zeugnis ist nicht zuverlässig.“',
        14: 'Jesus antwortete und sagte zu ihnen: „Auch wenn ich über mich selbst Zeugnis ablege, ist mein Zeugnis zuverlässig, weil ich weiß, woher ich gekommen bin und wohin ich gehe; ihr hingegen wisst nicht, woher ich komme oder wohin ich gehe.',
        15: 'Ihr richtet nach dem Fleisch, ich richte niemanden.',
        16: 'Aber auch wenn ich richte, ist mein Urteil wahr, weil ich nicht allein bin, sondern ich und der Vater, der mich geschickt hat.',
        17: 'Und auch in eurem Gesetz steht geschrieben, dass das Zeugnis von zwei Menschen zuverlässig ist.',
        18: 'Ich bin es, der Zeugnis ablegt über mich selbst, und der Vater, der mich geschickt hat, legt Zeugnis ab über mich.“',
        19: 'Darauf sagten sie zu ihm: „Wo ist dein Vater?“Jesus antwortete: „Ihr kennt weder mich noch meinen Vater! Wenn ihr mich kennen würdet, dann würdet ihr auch meinen Vater kennen.“',
        20: 'Diese Worte redete er in der Schatzkammer, während er im Tempel lehrte; und niemand verhaftete ihn, weil seine Stunde noch nicht gekommen war.',
        21: 'Darauf sprach er erneut zu ihnen: „Ich gehe, und ihr werdet mich suchen, und in eurer Sünde werdet ihr sterben; wohin ich gehe, könnt ihr nicht kommen.“',
        22: 'Da sagten die Judäer: „Wird er etwa sich selbst töten, dass er sagt: ‚Wohin ich gehe, könnt ihr nicht kommen‘?“',
        23: 'Und er sagte zu ihnen: „Ihr seid von dem, was unten [ist], ich bin von dem, was oben [ist]; ihr seid von dieser Welt, ich bin nicht von dieser Welt.',
        24: 'Also habe ich zu euch gesagt, dass ihr sterben werdet in euren Sünden. Denn wenn ihr nicht glaubt, dass ich es bin, dann werdet ihr sterben in euren Sünden.“',
        25: 'Darauf sagten sie zu ihm: „Du, wer bist du?“Jesus sagte zu ihnen: „Zunächst einmal das, was ich euch sage.“',
        26: 'Vieles habe ich über euch zu reden und zu urteilen, doch der mich geschickt hat, ist wahrhaftig, und was ich von ihm gehört habe, das rede ich zur Welt.“',
        27: 'Sie erkannten nicht, dass er vom Vater zu ihnen sprach.',
        28: 'Da sagte Jesus zu ihnen: „Wenn ihr den Menschensohn erhöht habt, dann werdet ihr erkennen, dass ich bin, und von mir selbst aus tue ich nichts, sondern wie mich der Vater gelehrt hat, das rede ich.',
        29: 'Und der mich geschickt hat, ist bei mir; er hat mich nicht alleingelassen, weil ich immer tue, was ihm gefällt.“',
        30: 'Als er das sagte, glaubten viele an ihn.',
        31: 'Dann sagte Jesus zu den Judäern, die zum Glauben an ihn gekommen waren: „Wenn ihr bleibt in meinem Wort, dann seid ihr wirklich meine Jünger,',
        32: 'und ihr werdet die Wahrheit erkennen, und die Wahrheit wird euch frei machen.“',
        33: 'Sie antworteten ihm: „Abrahams Nachkommenschaft sind wir, und wir haben noch nie irgendjemandem gedient! Wieso sagst du: ‚Ihr sollt frei werden‘?“',
        34: 'Jesus antwortete ihnen: „Amen, amen, ich sage euch: Jeder, der die Sünde tut, ist ein Sklave der Sünde.',
        35: 'Der Sklave aber bleibt nicht ‹für immer› im Haus; der Sohn bleibt ‹für immer›.',
        36: 'Wenn euch also der Sohn frei macht, dann werdet ihr wirklich frei sein.',
        37: 'Ich weiß, dass ihr Abrahams Nachkommenschaft seid; doch ihr versucht, mich zu töten, weil mein Wort unter euch keinen Platz findet.',
        38: 'Was ich beim Vater gesehen habe, rede ich. Also sollt auch ihr tun, was ihr beim Vater gehört habt!“',
        39: 'Sie antworteten und sagten zu ihm: „Unser Vater ist Abraham!“Jesus sagt zu ihnen: „Wenn ihr Kinder Abrahams wärt, dann würdet ihr die Werke Abrahams tun!',
        40: 'Tatsächlich aber versucht ihr, mich zu töten – einen Menschen, der ich euch die Wahrheit gesagt habe, die ich von Gott hörte. Das hat Abraham nicht getan!',
        41: 'Ihr tut die Werke eures [eigentlichen] Vaters.“Darauf sagten sie zu ihm: „Wir sind nicht aus Unzucht geboren, einen Vater haben wir: Gott.“',
        42: 'Jesus sagte zu ihnen: „Wenn Gott euer Vater wäre, dann würdet ihr mich lieben, denn ich bin von Gott ausgegangen und gekommen; ich bin nämlich auch nicht von mir selbst aus gekommen, sondern jener hat mich gesandt.',
        43: 'Weshalb versteht ihr mein Reden nicht? Weil ihr mein Wort nicht hören könnt.',
        44: 'Ihr seid aus dem Vater, dem Teufel, und die Begierden eures Vaters wollt ihr tun. Jener war ein Menschenmörder von Anfang an, und er stand nicht in der Wahrheit, weil in ihm keine Wahrheit ist. Wann immer er die Lüge ausspricht, redet er von den eigenen [Dingen], weil er ein Lügner ist und ihr Vater.',
        45: 'Dass ich hingegen die Wahrheit sage, glaubt ihr mir nicht.',
        46: 'Wer von euch überführt mich hinsichtlich einer Sünde? Wenn ich die Wahrheit sage, weshalb glaubt ihr mir nicht?',
        47: 'Wer aus Gott ist, hört die Worte Gottes; ihr hört deshalb nicht, weil ihr nicht aus Gott seid.“',
        48: 'Die Judäer antworteten und sagten zu ihm: „Sagen wir nicht zu Recht, dass du ein Samariter bist und einen Dämon hast?“',
        49: 'Jesus antwortete: „Ich habe keinen Dämon, sondern ich ehre meinen Vater, und ihr entehrt mich.',
        50: 'Ich aber suche nicht meine Ehre; es gibt einen, der sucht und richtet.',
        51: 'Amen, amen, ich sage euch: Wenn jemand mein Wort hält, dann wird er den Tod ‹unter keinen Umständen› sehen.“',
        52: 'Darauf sagten die Judäer zu ihm: „Jetzt haben wir erkannt, dass du einen Dämon hast. Abraham und die Propheten sind gestorben, und du sagst: ‚Wenn jemand mein Wort hält, dann wird er den Tod ‹unter keinen Umständen› schmecken.‘',
        53: 'Bist du etwa größer als unser Vater Abraham, der gestorben ist? Auch die Propheten sind gestorben. ‹Für wen hältst› du dich selbst?“',
        54: 'Jesus antwortete: „Wenn ich mich selbst verherrliche, dann ist meine Herrlichkeit nichts. Mein Vater ist es, der mich verherrlicht, von dem ihr sagt: ‚Er ist unser Gott.‘',
        55: 'Und ihr habt ihn nicht erkannt, ich aber kenne ihn. Und wenn ich sagen würde: ‚Ich kenne ihn nicht‘, dann wäre ich euch gleich: ein Lügner. Doch ich kenne ihn, und sein Wort halte ich.',
        56: 'Abraham, euer Vater, jubelte, dass er meinen Tag sehen sollte, und er hat ihn gesehen und sich gefreut.“',
        57: 'Darauf sagten die Judäer zu ihm: „Nicht einmal fünfzig Jahre bist du alt, und du hast Abraham gesehen?“',
        58: 'Jesus sagte zu ihnen: „Amen, amen, ich sage euch: Bevor Abraham wurde, bin ich.“',
        59: 'Da hoben sie Steine auf, um sie auf ihn zu werfen. Jesus aber versteckte sich, und er ging aus dem Tempel hinaus.',
    },
    9: {
        1: 'Und während er weiterzog, sah er einen Menschen, [der war] blind von Geburt an.',
        2: 'Und seine Jünger fragten ihn und sagten: „Rabbi, wer hat gesündigt, er oder seine Eltern, dass er blind geboren wurde?“',
        3: 'Jesus antwortete: „Weder er hat gesündigt noch seine Eltern, sondern [er ist blind], damit die Werke Gottes an ihm sichtbar werden.',
        4: 'Wir müssen die Werke dessen wirken, der mich geschickt hat, solange es Tag ist; es kommt eine Nacht, in der niemand wirken kann.',
        5: 'Solange ich in der Welt bin, bin ich das Licht der Welt.“',
        6: 'Nachdem er dies gesagt hatte, spuckte er auf den Boden, und er machte einen Brei aus der Spucke, und er strich ihm den Brei auf die Augen,',
        7: 'und er sagte zu ihm: „Geh, wasche dich in dem Teich von Schiloach!“(was sich übersetzen lässt: Gesandter). Darauf ging er hin und wusch sich, und er kam sehend [wieder].',
        8: 'Die Nachbarn und diejenigen, die ihn früher gesehen hatten (dass er ein Bettler war), fingen nun an zu sagen: „Ist nicht er es, der [sonst] dasitzt und bettelt?“',
        9: 'Einige sagten: „Er ist es!“Andere sagten: „Nein, doch er ist ihm ähnlich.“Jener sagte: „Ich bin es.“',
        10: 'Darauf sagten sie zu ihm: „Wie wurden denn deine Augen geöffnet?“',
        11: 'Jener antwortete: „Der Mann, der ‚Jesus‘heißt, machte einen Brei, und er strich ihn auf meine Augen, und er sagte zu mir: ‚Geh nach Schiloach und wasche dich!‘Als ich dann hingegangen war und mich gewaschen hatte, konnte ich wieder sehen.“',
        12: 'Und sie sagten zu ihm: „Wo ist jener [Mann]?“Er sagt: „Ich weiß es nicht.“',
        13: 'Sie bringen ihn zu den Pharisäern, den ehemals Blinden.',
        14: 'Es war aber Sabbat an dem Tag, als Jesus den Brei gemacht und dessen Augen geöffnet hatte.',
        15: 'Also befragten ihn außerdem auch die Pharisäer, wie er wieder sehen konnte. Er aber sagte zu ihnen: „Einen Brei legte er auf meine Augen, dann wusch ich mich, und [jetzt] sehe ich.“',
        16: 'Darauf sagten einige von den Pharisäern: „Dieser Mensch ist nicht von Gott, weil er den Sabbat nicht hält.“Andere wiederum sagten: „Wie kann ein sündhafter Mensch solche Zeichen tun?“Und es gab eine Auseinandersetzung unter ihnen.',
        17: 'Also sagen sie erneut zu dem Blinden: „Was sagst du über ihn, weil er deine Augen geöffnet hat?“Er aber sagte: „Er ist ein Prophet.“',
        18: 'Die Judäer glaubten nun über ihn nicht, dass er blind gewesen war und wieder sehen konnte, bis sie die Eltern dessen gerufen hatten, der wieder sehen konnte,',
        19: 'und sie fragten sie und sagten: „Ist dies euer Sohn, von dem ihr sagt, dass er blind geboren wurde? Wieso sieht er denn jetzt?“',
        20: 'Darauf antworteten seine Eltern und sagten: „Wir wissen, dass dies unser Sohn ist und dass er blind geboren wurde;',
        21: 'aber wieso er jetzt sieht, wissen wir nicht, oder wer seine Augen geöffnet hat, wissen wir nicht. Fragt ihn! Er ‹ist alt genug›, er wird für sich selbst sprechen.“',
        22: 'Das sagten seine Eltern, weil sie die Judäer fürchteten; die Judäer hatten nämlich bereits beschlossen, dass, wenn ihn jemand als Gesalbten bekennt, er aus der Synagoge ausgeschlossen würde.',
        23: 'Deshalb sagten seine Eltern: „Er ‹ist alt genug›, fragt ihn!“',
        24: 'Darauf riefen sie den Mann, der blind gewesen war, zum zweiten [Mal], und sie sagten zu ihm: „Gib Gott die Ehre! Wir wissen, dass dieser Mensch ein Sünder ist.“',
        25: 'Darauf antwortete jener: „Ob er ein Sünder ist, weiß ich nicht; [aber] eines weiß ich: dass jetzt sehe, obwohl ich blind [gewesen] bin.“',
        26: 'Da sagten sie zu ihm: „Was hat er mit dir gemacht? Wie hat er deine Augen geöffnet?“',
        27: 'Er antwortete ihnen: „Ich habe es euch bereits gesagt, und ihr habt nicht zugehört! Warum wollt ihr es nochmal hören? Wollt etwa auch ihr seine Jünger werden?“',
        28: 'Und sie beschimpften ihn und sagten: „Du bist ein Jünger von ihm, wir hingegen sind Jünger von Mose.',
        29: 'Wir wissen, dass Gott zu Mose geredet hat, aber von ihm wissen wir nicht, woher er stammt.“',
        30: 'Der Mann antwortete, und er sagte zu ihnen: „Darin besteht ja das Erstaunliche, dass ihr nicht wisst, woher er stammt, und doch hat er meine Augen geöffnet.',
        31: 'Wir wissen, dass Gott Sünder nicht erhört, doch wenn jemand gottesfürchtig ist und seinen Willen tut, den erhört er.',
        32: 'Seit jeher hat man nicht gehört, dass jemand die Augen eines blind Geborenen geöffnet hat.',
        33: 'Wenn dieser [Mann] nicht von Gott wäre, dann könnte er gar nichts tun.“',
        34: 'Sie antworteten, und sie sagten zu ihm: „Völlig in Sünden wurdest du geboren, und du willst uns belehren?“Dann warfen sie ihn hinaus.',
        35: 'Jesus hörte davon, dass sie ihn hinausgeworfen hatten, und als er ihn fand, sagte er: „Glaubst du an den Menschensohn?“',
        36: 'Jener antwortete und sagte: „Und wer ist es, Herr, damit ich an ihn glaube?“',
        37: 'Jesus sagte zu ihm: „Du hast ihn sogar [schon] gesehen, und zwar der mit dir redet, jener ist es.“',
        38: 'Er aber sagte: „Ich glaube, Herr!“, und er warf sich vor ihm nieder.',
        39: 'Und Jesus sagte: „Zum Gericht bin ich in diese Welt gekommen, damit die sehen, die nicht sehen, und die blind werden, die sehen.“',
        40: '[Einige] von den Pharisäern, die bei ihm waren, hörten das, und sie sagten zu ihm: „Sind etwa auch wir blind?“',
        41: 'Jesus sagte zu ihnen: „Wenn ihr blind wärt, dann hättet ihr keine Sünde; tatsächlich aber sagt ihr: ‚Wir sehen.‘Eure Sünde bleibt [also].“',
    },
    10: {
        1: '„Amen, amen, ich sage euch: Wer nicht durch die Tür in den Stall der Schafe hineingeht, sondern woanders hinaufsteigt, der ist ein Dieb und Räuber;',
        2: 'aber wer durch die Tür hineingeht, ist der Hirte der Schafe.',
        3: 'Dem öffnet der Türhüter, und die Schafe hören auf seine Stimme, und seine Schafe ruft er beim Namen, und er führt sie hinaus.',
        4: 'Sobald er die Seinen alle hinausgebracht hat, geht er vor ihnen her, und die Schafe folgen ihm, weil sie seine Stimme kennen.',
        5: 'Einem Fremden hingegen werden sie gewiss nicht folgen, sondern sie werden vor ihm fliehen, weil sie die Stimme der Fremden nicht kennen.“',
        6: 'Diesen Vergleich sagte ihnen Jesus, jene aber verstanden nicht, was es war, das er zu ihnen redete.',
        7: 'Also sagte Jesus außerdem: „Amen, amen, ich sage euch: Ich bin die Tür zu den Schafen!',
        8: 'Alle, die vor mir gekommen sind, sind Diebe und Räuber, doch die Schafe haben nicht auf sie gehört.',
        9: 'Ich bin die Tür! Wenn jemand durch mich hineingeht, wird er gerettet werden, und er wird ein- und ausgehen und Weide finden.',
        10: 'Der Dieb kommt nur, um zu stehlen und zu schlachten und zunichtezumachen. Ich bin gekommen, damit sie Leben haben, und ‹das reichlich›.',
        11: 'Ich bin der gute Hirte! Der gute Hirte legt sein Leben hin für die Schafe.',
        12: 'Wer ein Lohnarbeiter und nicht Hirte ist, dem [also] die Schafe nicht als Eigentum gehören, der sieht den Wolf kommen, und er lässt die Schafe zurück und flieht – und der Wolf erbeutet sie und zerstreut sie –,',
        13: 'weil er ein Lohnarbeiter ist und ihm nichts an den Schafen liegt.',
        14: 'Ich bin der gute Hirte, und ich kenne die Meinen, und die Meinen kennen mich,',
        15: 'so wie mich der Vater kennt und ich den Vater kenne, und mein Leben lege ich hin für die Schafe.',
        16: 'Und ich habe weitere Schafe, die nicht aus diesem Stall sind; auch sie muss ich führen, und sie werden auf meine Stimme hören, und es wird eine Herde [und] einen Hirten geben.',
        17: 'Deshalb liebt mich der Vater, weil ich mein Leben hinlege, um es wieder zu nehmen.',
        18: 'Keiner nimmt es von mir, sondern ich lege es von mir selbst aus hin. Ich habe Macht, es hinzulegen, und ich habe Macht, es wieder zu nehmen; diesen Auftrag habe ich von meinem Vater erhalten.“',
        19: 'Erneut entstand eine Auseinandersetzung unter den Judäern wegen dieser Worte.',
        20: 'Es sagten aber viele von ihnen: „Er hat einen Dämon und ist wahnsinnig! Warum hört ihr auf ihn?“',
        21: 'Andere sagten: „Das sind nicht die Worte eines Besessenen! Kann etwa ein Dämon die Augen der Blinden öffnen?“',
        22: 'Damals fand das Fest der Tempelweihe in Jerusalem statt, es war Winter,',
        23: 'und Jesus ging im Tempel umher, in der Säulenhalle Salomos.',
        24: 'Da umringten ihn die Judäer, und sie sagten zu ihm: „Bis wann hältst du uns hin? Wenn du der Gesalbte bist, dann sag es uns frei heraus!“',
        25: 'Jesus antwortete ihnen: „Ich habe es euch gesagt, aber ihr glaubt es nicht! Die Werke, die ich tue im Namen meines Vaters, sie legen Zeugnis ab über mich;',
        26: 'doch ihr glaubt nicht, weil ihr nicht zu meinen Schafen gehört.',
        27: 'Meine Schafe hören auf meine Stimme, und ich kenne sie, und sie folgen mir,',
        28: 'und ich gebe ihnen ewiges Leben, und sie gehen ‹unter keinen Umständen› verloren, und es wird sie niemand aus meiner Hand rauben.',
        29: 'Was mein Vater mir gegeben hat, ist größer als alles, und niemand kann sie aus der Hand des Vaters rauben.',
        30: 'Ich und der Vater sind eins.“',
        31: 'Die Judäer hoben erneut Steine auf, um ihn zu steinigen.',
        32: 'Jesus antwortete ihnen: „Viele gute Werke habe ich euch vom Vater gezeigt; wegen welchem ‹dieser Werke› steinigt ihr mich?“',
        33: 'Die Judäer antworteten ihm: „Für ein gutes Werk steinigen wir dich nicht, sondern für eine Lästerung, und zwar weil du, der du ein Mensch bist, dich selbst zu Gott machst!“',
        34: 'Jesus antwortete ihnen: „Steht nicht in eurem Gesetz geschrieben: ‚Ich habe gesagt: Götter seid ihr‘?',
        35: 'Wenn er jene ‚Götter‘nennt, an die das Wort Gottes ergangen ist, und die Schrift nicht aufgelöst werden kann,',
        36: '[mit welcher Berechtigung] sagt ihr dann zu dem, den der Vater geheiligt und in die Welt gesandt hat: ‚Du lästerst [Gott]‘, [nur] weil ich gesagt habe: ‚Ich bin Gottes Sohn‘?',
        37: 'Wenn ich nicht die Werke meines Vaters tue, dann glaubt mir nicht!',
        38: 'Aber wenn ich sie tue und ihr mir nicht glaubt, dann glaubt [wenigstens] den Werken, damit ihr erkennt und versteht, dass in mir der Vater [ist] und ich im Vater [bin].“',
        39: 'Darauf versuchten sie erneut, ihn zu verhaften, aber er entkam ihrem Zugriff.',
        40: 'Und er ging wieder auf die gegenüberliegende [Seite] des Jordans, an den Ort, wo Johannes zuerst getauft hatte, und er blieb dort.',
        41: 'Und viele kamen zu ihm, und sie sagten: „Johannes hat zwar kein einziges Zeichen getan, aber alles, was Johannes über diesen [Mann] gesagt hat, ist wahr.“',
        42: 'Und viele kamen dort zum Glauben an ihn.',
    },
    11: {
        1: 'Es war nun jemand krank, [nämlich] Lazarus von Betanien, aus dem Dorf von Maria und ihrer Schwester Marta.',
        2: '(Es war aber Maria, die den Herrn mit Duftöl gesalbt und seine Füße mit ihren Haaren trocken gerieben hatte; deren Bruder Lazarus war krank.)',
        3: 'Also sandten die Schwestern [eine Nachricht] zu ihm und sagten: „Herr, siehe!, der, den du lieb hast, ist krank.“',
        4: 'Als nun Jesus das hörte, sagte er: „Diese Krankheit führt nicht zum Tod, sondern [geschieht] um der Verherrlichung Gottes willen, damit der Sohn Gottes verherrlicht wird durch sie.“',
        5: 'Jesus aber hatte Marta und ihre Schwester und Lazarus liebgewonnen.',
        6: 'Wie er also hörte, dass er krank war, blieb er daraufhin zwei Tage an dem Ort, wo er war.',
        7: 'Erst danach sagt er zu den Jüngern: „Lasst uns wieder nach Judäa aufbrechen!“',
        8: 'Die Jünger sagen zu ihm: „Rabbi, eben versuchten dich die Judäer zu steinigen, und wieder gehst du dorthin?“',
        9: 'Jesus antwortete: „Hat der Tag nicht zwölf Stunden? Wenn jemand am Tag umhergeht, dann stolpert er nicht, weil er das Licht dieser Welt sieht;',
        10: 'aber wenn jemand in der Nacht umhergeht, dann stolpert er, weil das Licht nicht in ihm ist.“',
        11: 'Das sagte er, und danach sagt er zu ihnen: „Unser Freund Lazarus ist eingeschlafen; doch ich gehe, um ihn aufzuwecken.“',
        12: 'Darauf sagten die Jünger zu ihm: „Herr, wenn er eingeschlafen ist, wird er geheilt werden.“',
        13: 'Nun hatte Jesus über seinen Tod gesprochen, jene aber meinten, dass er über den ‹gewöhnlichen Schlaf› spricht.',
        14: 'Daraufhin sagte Jesus also offen zu ihnen: „Lazarus ist gestorben,',
        15: 'und ich freue mich euretwegen, dass ich nicht dort war, damit ihr glaubt; doch lasst uns zu ihm aufbrechen!“',
        16: 'Da sagte Thomas, der Didymus heißt, zu den Mitjüngern: „Lasst auch uns aufbrechen, um mit ihm zu sterben!“',
        17: 'Als dann Jesus kam, stellte er fest, dass er bereits vier Tage in der Grabhöhle lag.',
        18: 'Nun war Betanien nahe bei Jerusalem, etwa fünfzehn Stadien entfernt.',
        19: 'Aber viele von den Judäern waren zu Marta und Maria gekommen, um sie anlässlich [ihres] Bruders zu trösten.',
        20: 'Als nun Marta hörte, dass Jesus kommt, ging sie ihm entgegen; Maria aber blieb im Haus sitzen.',
        21: 'Da sagte Marta zu Jesus: „Herr, wenn du hier gewesen wärst, dann wäre mein Bruder nicht gestorben!',
        22: 'Doch auch jetzt weiß ich: Was auch immer du Gott bittest, wird Gott dir geben.“',
        23: 'Jesus sagt zu ihr: „Dein Bruder wird auferstehen.“',
        24: 'Marta sagt zu ihm: „Ich weiß, dass er auferstehen wird bei der Auferstehung am letzten Tag.“',
        25: 'Jesus sagte zu ihr: „Ich bin die Auferstehung und das Leben! Wer an mich glaubt, wird leben, auch wenn er stirbt.',
        26: 'Und jeder, der lebt und an mich glaubt, stirbt ‹unter keinen Umständen›. Glaubst du das?“',
        27: 'Sie sagt zu ihm: „Ja, Herr! Ich glaube fest, dass du der Gesalbte bist, der Sohn Gottes, der in die Welt kommt.“',
        28: 'Und nachdem sie dies gesagt hatte, ging sie fort, und sie rief heimlich ihre Schwester Maria und sagte: „Der Lehrer ist da, und er ruft dich.“',
        29: 'Jene wiederum, als sie es hörte, stand schnell auf, und sie ging zu ihm.',
        30: 'Jesus war aber noch nicht in das Dorf gekommen, sondern er war noch an dem Ort, wo Marta ihm begegnet war.',
        31: 'Als nun die Judäer, die bei ihr im Haus waren und sie trösteten, Maria sahen, dass sie schnell aufstand und hinausging, da folgten sie ihr, weil sie meinten, dass sie zu der Grabhöhle gehen würde, um dort zu weinen.',
        32: 'Als nun Maria hinkam, wo Jesus war, und ihn sah, fiel sie zu seinen Füßen nieder und sagte zu ihm: „Herr, wenn du hier gewesen wärst, dann wäre mein Bruder nicht gestorben.“',
        33: 'Als nun Jesus sie und die Judäer, die sie begleitet hatten, weinen sah, erzürnte er im Innersten, und er regte sich auf,',
        34: 'und er sagte: „Wo habt ihr ihn hingelegt?“Sie sagen zu ihm: „Herr, komm und sieh!“',
        35: 'Jesus weinte.',
        36: 'Darauf sagten die Judäer: „Siehe!, wie [sehr] er ihn lieb hatte.“',
        37: 'Aber einige von ihnen sagten: „Konnte er, der die Augen des Blinden geöffnet hat, nicht dafür sorgen, dass auch dieser nicht stirbt?“',
        38: 'Jesus erzürnt nun erneut innerlich und kommt zu der Grabhöhle; nun war es eine Höhle, und ein Stein lag davor.',
        39: 'Jesus sagt: „Nehmt den Stein weg!“Marta, die Schwester des Verstorbenen, sagt zu ihm: „Herr, er stinkt schon, denn es ist der vierte Tag.“',
        40: 'Jesus sagt zu ihr: „Habe ich dir nicht gesagt, dass du die Herrlichkeit Gottes sehen wirst, wenn du glaubst?',
        41: 'Darauf nahmen sie den Stein weg. Jesus aber hob die Augen empor, und er sagte: „Vater, ich danke dir, dass du mich erhört hast.',
        42: 'Ich wusste, dass du mich jederzeit erhörst, doch um der Menschenmenge willen, die umhersteht, habe ich es gesagt, damit sie glauben, dass du mich gesandt hast.“',
        43: 'Und nachdem er das gesagt hatte, rief er mit lauter Stimme: „Lazarus, komm nach draußen!“',
        44: 'Der Verstorbene kam heraus, die Beine und Arme mit Tüchern gebunden, und sein Gesicht war mit einem Schweißtuch umwickelt. Jesus sagt zu ihnen: „Macht ihn los und lasst ihn gehen!“',
        45: 'Viele von den Judäern nun, die zu Maria gekommen waren und gesehen hatten, was er getan hatte, kamen zum Glauben an ihn;',
        46: 'aber einige von ihnen gingen zu den Pharisäern, und sie sagten ihnen, was Jesus getan hatte.',
        47: 'Darauf versammelten die Oberpriester und die Pharisäer das Synedrium, und sie sagten: „Was tun wir [dagegen], dass dieser Mensch viele Zeichen tut?',
        48: 'Wenn wir ihn so [weitermachen] lassen, werden alle an ihn glauben, und dann werden die Römer kommen und uns sowohl die Stätte als auch das Volk wegnehmen.“',
        49: 'Aber einer von ihnen – ein gewisser Kajaphas, der in jenem Jahr Oberpriester war – sagte zu ihnen: „Ihr wisst gar nichts,',
        50: 'und ihr berücksichtigt nicht, dass es besser für euch ist, dass ein einziger Mensch für das Volk stirbt und nicht die gesamte Nation umkommt.“',
        51: 'Das sagte er aber nicht von sich aus, sondern weil er in jenem Jahr Oberpriester war, weissagte er, dass Jesus für die Nation sterben würde,',
        52: 'und nicht nur für die Nation, sondern auch, um die verstreuten Kinder Gottes zu einem [Ganzen] zu versammeln.',
        53: 'Von jenem Tag an beratschlagten sie also, ihn zu töten.',
        54: 'Jesus ging also nicht länger öffentlich unter den Judäern umher, sondern er ging von dort weg in die Gegend nahe der Wüste, in eine Stadt, die hieß Efraïm, und dort blieb er mit den Jüngern.',
        55: 'Nun war das Passa der Judäer nahe, und es stiegen viele aus der Gegend vor dem Passa nach Jerusalem hinauf, um sich zu reinigen.',
        56: 'Da suchten sie Jesus, und sie sprachen miteinander, während sie im Tempel standen: „Was meint ihr? Dass er gewiss nicht zu dem Fest kommt?“',
        57: 'Die Oberpriester und die Pharisäer hatten aber Gebote erlassen, dass, wenn jemand erfährt, wo er sei, er Anzeige erstatten solle, damit sie ihn verhaften könnten.',
    },
    12: {
        1: 'Jesus kam dann sechs Tage vor dem Passa nach Betanien, wo Lazarus lebte, den Jesus auferweckt hatte von den Toten.',
        2: 'Also bereiteten sie ihm dort eine Mahlzeit, und Marta bediente, Lazarus aber war einer von denen, die mit ihm [zu Tisch] lagen.',
        3: 'Maria nahm nun ein Pfund Duftöl aus echter, kostbarer Narde und salbte die Füße von Jesus, und sie trocknete seine Füße mit ihren Haaren; das Haus aber wurde vom Geruch des Duftöls erfüllt.',
        4: 'Da sagt Judas Iskariot, einer von seinen Jüngern, [und zwar der], der ihn verraten würde:',
        5: '„Weshalb wurde dieses Duftöl nicht für dreihundert Denare verkauft und [der Erlös] den Armen gegeben?“',
        6: 'Das sagte er aber nicht, weil es ihm um die Armen ging, sondern weil er ein Dieb war und er die Kasse hatte und wiederholt die eingeworfenen [Spenden] entwendete.',
        7: 'Also sagte Jesus: „Lasst sie: Für den Tag meines Begräbnisses hat sie dies aufbewahrt.',
        8: 'Denn die Armen habt ihr immer bei euch, mich hingegen habt ihr nicht immer.“',
        9: 'Es erfuhr nun eine große Menge von den Judäern, dass er dort war, und sie kamen nicht nur wegen Jesus, sondern auch um Lazarus zu sehen, den er auferweckt hatte von den Toten.',
        10: 'Da beschlossen die Oberpriester, auch Lazarus zu töten,',
        11: 'weil viele Judäer seinetwegen hingingen und an Jesus glaubten.',
        12: 'Am folgenden [Tag] hörten sie – die große Menschenmenge, die zu dem Fest gekommen war –, dass Jesus nach Jerusalem kommen würde, und',
        13: 'nahmen Palmenzweige, und sie gingen hinaus zur Begegnung mit ihm, und sie schrien: „Hosanna! Gepriesen ist, der kommt im Namen des Herrn, und der König Israels!“',
        14: 'Da fand Jesus einen jungen Esel und setzte sich darauf, wie geschrieben steht:',
        15: '„Fürchte dich nicht, Tochter Zion! / Siehe, dein König kommt / und sitzt auf einem Eselsfohlen.“',
        16: '(Dies verstanden seine Jünger zunächst nicht, doch nachdem Jesus verherrlicht worden war, dann erinnerten sie sich, dass dies über ihn geschrieben stand und sie dies für ihn getan hatten.)',
        17: 'Die Menschenmenge, die bei ihm war, als er Lazarus aus der Grabhöhle gerufen und ihn von den Toten auferweckt hatte, legte also Zeugnis ab.',
        18: 'Deshalb zog ihm die Menschenmenge auch entgegen, weil sie gehört hatten, dass er dieses Zeichen getan hatte.',
        19: 'Da sagten die Pharisäer zu sich: „Ihr seht, dass ihr gar nichts ausrichtet; siehe!, die Welt läuft ihm hinterher.“',
        20: 'Es waren aber einige Griechen unter denen, die hinaufstiegen, um bei dem Fest anzubeten;',
        21: 'diese kamen nun zu Philippus (dem aus Betsaïda in Galiläa), und sie baten ihn und sagten: „Herr, wir wollen Jesus sehen!“',
        22: 'Philippus geht und sagt es Andreas; Andreas und Philippus gehen und sagen es Jesus.',
        23: 'Jesus wiederum antwortet ihnen und sagt: „Die Stunde ist gekommen, dass der Menschensohn verherrlicht wird.',
        24: 'Amen, amen, ich sage euch: Wenn das Weizenkorn nicht in die Erde fällt und stirbt, bleibt es allein; aber wenn es stirbt, bringt es viel Frucht.',
        25: 'Wer sein Leben liebt, verliert es, und wer sein Leben in dieser Welt hasst, wird es bewahren zum ewigen Leben.',
        26: 'Wenn mir jemand dient, dann soll er mir folgen, und wo ich bin, dort wird auch mein Diener sein; wenn jemand mir dient, dann wird ihn der Vater ehren.“',
        27: '„Jetzt ist meine Seele aufgewühlt, aber was soll ich sagen? ‚Vater, rette mich aus dieser Stunde!‘? Deshalb bin ich doch in diese Stunde gekommen.',
        28: 'Vater, verherrliche deinen Namen!“Darauf kam eine Stimme vom Himmel: „Ich habe ihn verherrlicht, und ich werde ihn erneut verherrlichen.“',
        29: 'Die Menschenmenge, die dabeistand und es hörte, sagte nun, ein Donner sei geschehen; andere sagten: „Ein Engel hat zu ihm geredet.“',
        30: 'Jesus antwortete und sagte: „Nicht um meinetwillen ist diese Stimme geschehen, sondern um euretwillen.',
        31: 'Jetzt ist [Zeit für] das Gericht über diese Welt, jetzt wird der Fürst dieser Welt hinausgeworfen werden;',
        32: 'und ich – wenn ich von der Erde erhöht worden bin – werde alle zu mir ziehen.“',
        33: '(Das aber sagte er, um anzudeuten, durch welchen Tod er sterben würde.)',
        34: 'Darauf antwortete ihm die Menschenmenge: „Wir haben aus dem Gesetz gehört, dass der Gesalbte ‹für immer› bleibt; wieso sagst du dann, dass der Menschensohn erhöht werden muss? Wer ist dieser ‚Menschensohn‘?“',
        35: 'Da sagte Jesus zu ihnen: „Noch kurze Zeit ist das Licht unter euch. Lebt, solange ihr das Licht habt, damit nicht Finsternis euch erfasst! Und wer in der Finsternis lebt, weiß nicht, wohin er geht.',
        36: 'Solange ihr das Licht habt, glaubt an das Licht, damit ihr Kinder des Lichts werdet!“Davon redete Jesus, und dann ging er fort und verbarg sich vor ihnen.',
        37: 'Aber obwohl er so viele Zeichen vor ihnen getan hatte, glaubten sie nicht an ihn,',
        38: 'sodass sich das Wort des Propheten Jesaja erfüllte, das er gesagt hatte: „Herr, wer hat unserer Botschaft geglaubt? / Und wem ist der Arm des Herrn offenbart worden?“',
        39: 'Deshalb konnten sie nicht glauben, weil Jesaja außerdem gesagt hat:',
        40: '„Er hat ihre Augen blind gemacht / und ihr Herz verhärtet, / sodass sie mit den Augen nicht sehen / und mit dem Herzen nicht verstehen / und sie nicht umkehren und ich sie heilen würde.“',
        41: 'Das sagte Jesaja, weil er seine Herrlichkeit gesehen hatte, und von ihm hat er geredet.',
        42: 'Trotzdem glaubten auch von den Vorstehern viele an ihn, doch wegen der Pharisäer bekannten sie es nicht, um nicht aus der Synagoge ausgeschlossen zu werden;',
        43: 'denn sie schätzten die Ehre vonseiten der Menschen mehr als die Ehre vonseiten Gottes.',
        44: 'Jesus aber rief und sagte: „Wer an mich glaubt, glaubt nicht an mich, sondern an den, der mich geschickt hat,',
        45: 'und wer mich sieht, sieht den, der mich geschickt hat.',
        46: 'Ich bin als Licht in die Welt gekommen, damit jeder, der an mich glaubt, nicht in der Finsternis bleibt.',
        47: 'Und wenn jemand meine Worte hört und nicht befolgt, dann richte ich ihn nicht; ich bin nämlich nicht gekommen, um die Welt zu richten, sondern um die Welt zu retten.',
        48: 'Wer mich ablehnt und meine Worte nicht annimmt, hat, was ihn richtet: Das Wort, das ich geredet habe, das wird ihn richten am letzten Tag.',
        49: 'Denn ich habe nicht aus mir selbst heraus geredet, sondern der Vater, der mich geschickt hat, der hat mir ein Gebot gegeben, was ich sagen und was ich reden soll.',
        50: 'Und ich weiß, dass sein Gebot ewiges Leben bedeutet. Was ich also rede, rede ich so, wie es mir der Vater gesagt hat.“',
    },
    13: {
        1: 'Vor dem Passa aber, weil Jesus wusste, dass seine Stunde gekommen war, um aus dieser Welt hinüberzugehen zum Vater … weil er die Seinen liebte, die in der Welt [waren], liebte er sie bis zum Ende.',
        2: 'Und ‹im Verlauf des Abendessens›, als der Teufel schon [den Gedanken] ins Herz getan hatte, dass Judas, [der Sohn] von Simon Iskariot, ihn verraten sollte,',
        3: '[und] weil er wusste, dass ihm der Vater alles in die Hände gegeben hatte und dass er von Gott ausgegangen war und zu Gott hingehen würde,',
        4: 'steht er von dem Abendessen auf und legt die Obergewänder ab, und er nahm ein Leinentuch und umgürtete sich;',
        5: 'danach schüttet er Wasser in die Waschschüssel, und er begann, die Füße der Jünger zu waschen und mit dem Leinentuch zu trocknen, mit dem er umgürtet war.',
        6: 'Er kommt also zu Simon Petrus; [der] sagt zu ihm: „Herr, du wäschst meine Füße?“',
        7: 'Jesus antwortete und sagte zu ihm: „Was ich tue, verstehst du jetzt nicht, du wirst es aber danach verstehen.“',
        8: 'Petrus sagt zu ihm: „‹Unter keinen Umständen› sollst du meine Füße waschen!“Jesus antwortete ihm: „Wenn ich dich nicht wasche, hast du keinen Anteil an mir.“',
        9: 'Simon Petrus sagt zu ihm: „Herr, nicht nur meine Füße, sondern auch die Hände und den Kopf!“',
        10: 'Jesus sagt zu ihm: „Wer gebadet ist, hat es nicht nötig, sich zu waschen – außer die Füße –, sondern er ist völlig rein; auch ihr seid rein, jedoch nicht alle.“',
        11: 'Denn er kannte den, der ihn verraten würde; deshalb sagte er: „Ihr seid nicht alle rein.“',
        12: 'Nachdem er nun ihre Füße gewaschen und er seine Obergewänder genommen und wieder Platz genommen hatte, sagte er zu ihnen: „Versteht ihr, was ich an euch getan habe?',
        13: 'Ihr ruft mich ‚Lehrer‘und ‚Herr‘, und ihr sagt es zu Recht; denn [das] bin ich.',
        14: 'Wenn also ich, der Herr und Lehrer, eure Füße gewaschen habe, dann seid auch ihr verpflichtet, einander die Füße zu waschen.',
        15: 'Ich habe euch nämlich ein Beispiel gegeben, damit auch ihr handelt, so wie ich an euch gehandelt habe.',
        16: 'Amen, amen, ich sage euch: Ein Knecht ist nicht größer als sein Herr und ein Gesandter nicht größer als derjenige, der ihn geschickt hat.',
        17: 'Wenn ihr das wisst, seid ihr beglückwünschenswert, wenn ihr es tut!',
        18: 'Ich spreche nicht über euch alle; ich weiß, welche ich erwählt habe. Doch damit die Schrift erfüllt wird: ‚Der mein Brot isst, hat seine Ferse gegen mich erhoben.‘',
        19: 'Ab jetzt sage ich es euch, bevor es geschieht, damit ihr – sobald es geschieht – glaubt, dass ich es bin.',
        20: 'Amen, amen, ich sage euch: Wer aufnimmt, wen auch immer ich schicke, nimmt mich auf, und wer mich aufnimmt, nimmt den auf, der mich geschickt hat.“',
        21: 'Nachdem Jesus das gesagt hatte, wurde er im Innersten aufgewühlt, und er legte Zeugnis ab und sagte: „Amen, amen, ich sage euch, dass einer von euch mich verraten wird.“',
        22: 'Die Jünger blickten einander an und waren verunsichert, über wen er spricht.',
        23: 'Einer von seinen Jüngern lag an der Brust von Jesus (der, den Jesus liebgewonnen hatte).',
        24: 'Also gab Simon Petrus ihm Zeichen, sich zu erkundigen, wer es sein möge, über den er spricht.',
        25: 'Da lehnte sich jener so an die Brust von Jesus und sagt zu ihm: „Herr, wer ist es?“',
        26: 'Jesus antwortet: „Es ist jener, dem ich den Bissen eintauchen und geben werde.“Nachdem er also den Bissen eingetaucht hatte, nimmt er ihn und gibt ihn Judas, [dem Sohn] des Simon Iskariot.',
        27: 'Und nach dem Bissen fuhr dann der Satan in jenen hinein. Da sagt Jesus zu ihm: „Was du tun willst, tue bald!“',
        28: 'Warum er das aber zu ihm sagte, verstand keiner von denen, die [zu Tisch] lagen.',
        29: 'Denn einige meinten – weil Judas die Kasse hatte –, dass Jesus ihm sagte: „Kaufe, was wir für das Fest benötigen!“, oder dass er den Armen etwas geben sollte.',
        30: 'Als jener nun den Bissen genommen hatte, ging er sofort er hinaus. Es war aber Nacht.',
        31: 'Nachdem er also hinausgegangen war, sagt Jesus: „Jetzt wurde der Menschensohn verherrlicht, und Gott wurde in ihm verherrlicht.',
        32: 'Wenn Gott in ihm verherrlicht wurde, dann wird auch Gott ihn in sich verherrlichen, und er wird ihn unverzüglich verherrlichen.',
        33: 'Kinder, noch kurze [Zeit] bin ich bei euch. Ihr werdet mich suchen, und wie ich den Judäern gesagt habe: ‚Wo ich hingehe, könnt ihr nicht hinkommen‘, so sage ich es jetzt auch euch.',
        34: 'Ein neues Gebot gebe ich euch: dass ihr einander lieben sollt, wie ich euch geliebt habe, damit auch ihr einander liebt.',
        35: 'Daran werden alle erkennen, dass ihr meine Jünger seid: wenn ihr Liebe untereinander habt.“',
        36: 'Simon Petrus sagt zu ihm: „Herr, wo gehst du hin?“Jesus antwortete ihm: „Wo ich hingehe, kannst du mir jetzt nicht folgen, aber später wirst du folgen.“',
        37: 'Petrus sagt zu ihm: „Herr, weshalb kann ich dir jetzt nicht folgen? Mein Leben werde ich für dich hinlegen.“',
        38: 'Jesus antwortet: „Dein Leben wirst du für mich hinlegen? Amen, amen, ich sage dir: Der Hahn wird nicht krähen, bis du mich dreimal verleugnet hast.“',
    },
    14: {
        1: '„Euer Herz soll nicht erschrecken! Glaubt an Gott, und glaubt an mich!',
        2: 'Im Haus meines Vaters gibt es viele Wohnungen; aber wenn nicht, hätte ich dann zu euch gesagt: ‚Ich gehe, um einen Ort für euch vorzubereiten‘?',
        3: 'Und wenn ich gehe und einen Ort für euch vorbereite, dann komme ich wieder und ich werde euch zu mir nehmen, damit auch ihr seid, wo ich bin.',
        4: 'Und wo ich hingehe, dahin wisst ihr den Weg.“',
        5: 'Thomas sagt zu ihm: „Herr, wir wissen nicht, wo du hingehst; wie können wir den Weg wissen?!?“',
        6: 'Jesus sagt zu ihm: „Ich bin der Weg und die Wahrheit und das Leben! Niemand kommt zum Vater, außer durch mich.',
        7: 'Wenn ihr mich gekannt habt, dann werdet ihr auch meinen Vater kennen. Und von jetzt an kennt ihr ihn und habt ihr ihn gesehen.“',
        8: 'Philippus sagt zu ihm: „Herr, zeige uns den Vater, und es genügt uns.“',
        9: 'Jesus sagt zu ihm: „So lange Zeit bin ich [schon] bei euch, und du hast mich nicht gekannt, Philippus? Wer mich gesehen hat, hat den Vater gesehen. Wieso sagst du: ‚Zeige uns den Vater!‘?',
        10: 'Glaubst du nicht, dass ich im Vater [bin] und der Vater in mir ist? Die Worte, die ich euch sage, rede ich nicht von mir selbst aus; der Vater aber, der in mir bleibt, tut seine Werke.',
        11: 'Glaubt mir, dass ich im Vater [bin] und der Vater in mir [ist]. Aber wenn nicht, dann glaubt [wenigstens] wegen der Werke selbst.',
        12: 'Amen, amen, ich sage euch: Wer an mich glaubt, auch der wird die Werke tun, die ich tue, und größere als diese wird er tun, weil ich zum Vater gehe.',
        13: 'Und was auch immer ihr bittet in meinem Namen, das werde ich tun, damit der Vater verherrlicht wird durch den Sohn.',
        14: 'Wenn ihr mich um etwas bittet in meinem Namen, dann werde ich es tun.“',
        15: '„Wenn ihr mich liebt, dann werdet ihr meine Gebote halten.',
        16: 'Und ich werde den Vater bitten, und er wird euch einen anderen Fürsprecher geben, damit er ‹für immer› bei euch sei:',
        17: 'den Geist der Wahrheit, den die Welt nicht bekommen kann, weil sie ihn nicht sieht und nicht kennt; ihr kennt ihn, weil er bei euch bleibt und er in euch sein wird.',
        18: 'Ich werde euch nicht als Waisen zurücklassen; ich komme zu euch.',
        19: 'Noch kurze [Zeit], dann sieht die Welt mich nicht mehr, ihr aber seht mich; weil ich lebe, werdet auch ihr leben.',
        20: 'An jenem Tag werdet ihr erkennen, dass ich in meinem Vater [bin] und ihr in mir und ich in euch.',
        21: 'Wer meine Gebote hat und sie hält, der ist es, der mich liebt; und wer mich liebt, wird von meinem Vater geliebt werden, und auch ich werde ihn lieben, und ich werde mich ihm offenbaren.“',
        22: 'Judas (nicht Iskariot) sagt zu ihm: „Herr, und was ist geschehen, dass du dich uns offenbaren willst und nicht der Welt?“',
        23: 'Jesus antwortete und sagte zu ihm: „Wenn jemand mich liebt, dann wird er mein Wort halten, und mein Vater wird ihn lieben, und wir werden zu ihm kommen und bei ihm wohnen.',
        24: 'Wer mich nicht liebt, hält meine Worte nicht; und das Wort, das ihr hört, ist nicht meines, sondern das des Vaters, der mich geschickt hat.',
        25: 'Diese [Dinge] habe ich zu euch geredet, während ich mich bei euch aufhielt;',
        26: 'der Fürsprecher aber – der heilige Geist, den der Vater schicken wird in meinem Namen –, der wird euch alles lehren und wird euch an alles erinnern, was ich euch gesagt habe.',
        27: 'Frieden hinterlasse ich euch, meinen Frieden gebe ich euch; nicht wie die Welt gibt, gebe ich euch. Euer Herz soll nicht erschrecken und nicht ängstlich sein!',
        28: 'Ihr habt gehört, dass ich euch gesagt habe: ‚Ich gehe hin, und ich komme zu euch.‘Wenn ihr mich lieben würdet, dann hättet ihr euch gefreut, dass ich zum Vater gehe, weil der Vater größer ist als ich.',
        29: 'Und jetzt habe ich es euch gesagt, bevor es geschieht, damit ihr glaubt, sobald es geschieht.',
        30: 'Viel werde ich nicht mehr mit euch bereden, denn es kommt der Fürst der Welt; aber er hat keinerlei [Macht] über mich,',
        31: 'doch damit die Welt erkennt, dass ich den Vater liebe, handle ich auch so, wie es mir der Vater aufgetragen hat. Steht auf, lasst uns von hier aufbrechen!“',
    },
    15: {
        1: '„Ich bin der wahre Weinstock, und mein Vater ist der Weinbauer!',
        2: 'Jede Rebe an mir, die keine Frucht bringt, die entfernt er, und jede, die Furcht bringt, die reinigt er, damit sie [noch] mehr Frucht bringt.',
        3: 'Ihr seid schon rein wegen des Wortes, das ich zu euch geredet habe.',
        4: 'Bleibt in mir, [dann bleibe] auch ich in euch! Wie die Rebe nicht von sich aus Frucht bringen kann, wenn sie nicht am Weinstock bleibt, so auch ihr nicht, wenn ihr nicht in mir bleibt.',
        5: 'Ich bin der Weinstock, ihr die Reben! Wer in mir bleibt und ich in ihm, der trägt viel Frucht, weil ihr ohne mich gar nichts tun könnt.',
        6: 'Wenn jemand nicht in mir bleibt, dann wird er nach draußen geworfen wie die Rebe, und er verdorrt, und man sammelt sie und wirft sie ins Feuer, und sie verbrennen.',
        7: 'Wenn ihr in mir bleibt und meine Worte in euch bleiben, dann bittet, was auch immer ihr wollt, und es wird euch zukommen!',
        8: 'Dadurch wird mein Vater verherrlicht: dass ihr viel Frucht bringt und ihr meine Jünger werdet.',
        9: 'Wie mich der Vater geliebt hat, so habe auch ich euch geliebt. Bleibt in meiner Liebe!',
        10: 'Wenn ihr meine Gebote haltet, dann werdet ihr in meiner Liebe bleiben, so wie ich die Gebote meines Vaters gehalten habe und in seiner Liebe bleibe.',
        11: 'Diese [Dinge] habe ich zu euch geredet, damit meine Freude in euch ist und eure Freude erfüllt wird.',
        12: 'Dies ist mein Gebot: dass ihr einander liebt, wie ich euch geliebt habe.',
        13: 'Größere Liebe hat niemand als die, dass jemand sein Leben hinlegt für seine Freunde.',
        14: 'Ihr seid meine Freunde, wenn ihr tut, was ich euch gebiete.',
        15: 'Ich nenne euch nicht mehr Knechte, weil der Knecht nicht weiß, was sein Herr tut; euch aber habe ich Freunde genannt, weil ich euch alles wissen ließ, was ich bei meinem Vater gehört habe.',
        16: 'Nicht ihr habt mich erwählt, sondern ich habe euch erwählt, und ich habe euch dazu bestimmt, dass ihr geht und Frucht bringt und eure Frucht bleibt, damit er euch gebe, was auch immer ihr den Vater in meinem Namen bittet.',
        17: 'Diese [Dinge] gebiete ich euch, damit ihr einander liebt!“',
        18: '„Wenn die Welt euch hasst, dann macht euch bewusst, dass sie mich vor euch gehasst hat.',
        19: 'Wenn ihr von der Welt wärt, dann würde die Welt das Ihre lieb haben; aber weil ihr nicht von der Welt seid, sondern ich euch aus der Welt erwählt habe, deshalb hasst euch die Welt.',
        20: 'Erinnert euch an das Wort, das ich euch gesagt habe: Ein Knecht ist nicht größer als sein Herr. Wenn sie mich verfolgt haben, werden sie auch euch verfolgen; wenn sie mein Wort gehalten haben, dann werden sie auch eures halten.',
        21: 'Doch das alles werden sie euch antun wegen meines Namens, weil sie den nicht kennen, der mich geschickt hat.',
        22: 'Wenn ich nicht gekommen wäre und zu ihnen geredet hätte, dann hätten sie keine Sünde; aber jetzt haben sie keine Ausrede für ihre Sünde.',
        23: 'Wer mich hasst, hasst auch meinen Vater.',
        24: 'Wenn ich unter ihnen nicht die Werke getan hätte, die kein anderer getan hat, dann hätten sie keine Sünde; aber jetzt haben sie sowohl mich als auch meinen Vater gesehen und gehasst.',
        25: 'Doch [das geschieht], damit sich das Wort erfüllt, das in ihrem Gesetz geschrieben steht: ‚Sie haben mich grundlos gehasst.‘',
        26: 'Sobald der Fürsprecher gekommen ist, den ich euch vom Vater schicken werde – der Geist der Wahrheit, der vom Vater ausgeht –, wird jener Zeugnis ablegen über mich;',
        27: 'aber auch ihr legt Zeugnis ab, weil ihr von Anfang an bei mir seid.“',
    },
    16: {
        1: '„Diese [Dinge] habe ich zu euch geredet, damit ihr nicht Anstoß nehmt.',
        2: 'Sie werden euch ‹aus der Synagoge ausschließen›; doch es kommt die Stunde, dass jeder, der euch tötet, Gott einen Dienst zu erweisen meint.',
        3: 'Und diese [Dinge] werden sie tun, weil sie weder den Vater noch mich gekannt haben.',
        4: 'Doch diese [Dinge] habe ich zu euch geredet, damit ihr euch – sobald die Stunde dafür kommt – daran erinnert, dass ich es euch gesagt habe.“„Diese [Dinge] aber habe ich euch nicht von Anfang an gesagt, weil ich bei euch war.',
        5: 'Aber jetzt gehe ich zu dem hin, der mich geschickt hat, und keiner von euch fragt mich: ‚Wo gehst du hin?‘',
        6: 'Sondern weil ich diese [Dinge] zu euch geredet habe, hat die Traurigkeit euer Herz erfüllt.',
        7: 'Doch ich sage euch die Wahrheit: Es ist besser für euch, dass ich fortgehe. Denn wenn ich nicht fortgehe, dann wird der Fürsprecher nicht zu euch kommen; aber wenn ich gehe, dann werde ich ihn zu euch schicken.',
        8: 'Und wenn er kommt, wird jener die Welt aufklären über Sünde und über Gerechtigkeit und über Gericht:',
        9: 'über Sünde, dass sie nicht an mich glauben;',
        10: 'und über Gerechtigkeit, dass ich zum Vater gehe und ihr mich nicht mehr seht;',
        11: 'und über Gericht, dass der Fürst dieser Welt gerichtet ist.',
        12: 'Noch vieles habe ich euch zu sagen, doch ihr könnt es jetzt nicht ertragen;',
        13: 'aber sobald jener kommt, der Geist der Wahrheit, wird er euch in aller Wahrheit anleiten; er wird nämlich nicht von sich aus reden, sondern er wird alles sagen, was er hören wird, und die kommenden [Dinge] wird er euch verkünden.',
        14: 'Jener wird mich verherrlichen, weil er von dem Meinen nehmen und es euch verkünden wird.',
        15: 'Alles, was der Vater hat, ist mein; deshalb habe ich gesagt, dass er von dem Meinen nimmt und es euch verkünden wird.“',
        16: '„Eine kurze [Zeit], dann seht ihr mich nicht mehr, und wieder eine kurze [Zeit], dann werdet ihr mich sehen.“',
        17: 'Da sagten [einige] von seinen Jüngern zueinander: „Was bedeutet das, was er zu uns sagt: ‚Eine kurze [Zeit], dann seht ihr mich nicht, und wieder eine kurze [Zeit], dann werdet ihr mich sehen‘, und: ‚Ich gehe zum Vater hin‘?“',
        18: 'Sie sagten also: „Was bedeutet diese ‚kurze [Zeit]‘, von der er spricht? Wir wissen nicht, was er redet.“',
        19: 'Jesus merkte, dass sie ihn fragen wollten, und er sagte zu ihnen: „Rätselt ihr miteinander darüber, dass ich gesagt habe: ‚Eine kurze [Zeit], dann seht ihr mich nicht, und wieder eine kurze [Zeit], dann werdet ihr mich sehen‘?',
        20: 'Amen, amen, ich sage euch: Ihr werdet weinen und wehklagen, aber die Welt wird sich freuen; ihr werdet traurig sein, doch eure Traurigkeit wird zu Freude werden.',
        21: 'Die Frau hat Kummer, wann immer sie entbinden soll, weil ihre Stunde gekommen ist; aber sobald sie das Kind geboren hat, erinnert sie sich nicht mehr an die Not wegen der Freude, dass ein Mensch in die Welt geboren worden ist.',
        22: 'Auch ihr habt also jetzt Kummer, aber ich werde euch wiedersehen, und euer Herz wird sich freuen, und eure Freude nimmt euch keiner.',
        23: 'Und an jenem Tag werdet ihr mich gar nichts fragen. Amen, amen, ich sage euch: Was auch immer ihr den Vater bittet in meinem Namen, wird er euch geben.',
        24: 'Bis jetzt habt ihr gar nichts erbeten in meinem Namen; bittet, dann werdet ihr bekommen, damit eure Freude erfüllt ist!“',
        25: '„Diese [Dinge] habe ich in Vergleichen zu euch geredet; es kommt eine Stunde, in der ich nicht mehr in Vergleichen zu euch reden werde, sondern ich werde euch offen über den Vater berichten.',
        26: 'An jenem Tag werdet ihr in meinem Namen bitten, und ich sage euch nicht, dass ich den Vater für euch bitten werde;',
        27: 'denn er, der Vater, liebt euch, weil ihr mich geliebt habt und geglaubt habt, dass ich von Gott ausgegangen bin.',
        28: 'Ich bin vom Vater ausgegangen und in die Welt gekommen; [jetzt] verlasse ich die Welt wieder und gehe zum Vater.“',
        29: 'Seine Jünger sagen: „Siehe!, jetzt redest du offen und verwendest keinerlei Vergleich.',
        30: 'Jetzt wissen wir, dass du alles weißt und es nicht nötig hast, dass dich jemand fragt; dadurch glauben wir, dass du von Gott ausgegangen bist.“',
        31: 'Jesus antwortete ihnen: „Jetzt glaubt ihr?',
        32: 'Siehe!, es kommt die Stunde (und sie ist gekommen), dass ihr verstreut werdet – ein jeder ‹zu sich nach Hause› – und ihr mich allein lasst; aber ich bin nicht allein, weil der Vater bei mir ist.',
        33: 'Diese [Dinge] habe ich zu euch geredet, damit ihr in mir Frieden habt. In der Welt habt ihr Bedrängnis; doch seid guten Mutes, ich habe die Welt überwunden!“',
    },
    17: {
        1: 'Diese [Dinge] redete Jesus, und nachdem er seine Augen zum Himmel aufgehoben hatte, sagte er: „Vater, die Stunde ist gekommen. Verherrliche deinen Sohn, damit der Sohn dich verherrlicht!',
        2: 'Schließlich hast du ihm Vollmacht gegeben über die ganze Menschheit, damit er ihnen alles gibt, was du ihm gegeben hast: ewiges Leben.',
        3: 'Dies aber ist das ewige Leben: dass sie dich, den allein wahren Gott, erkennen und den du gesandt hast, Jesus Christus.',
        4: 'Ich habe dich verherrlicht auf der Erde, indem ich das Werk vollendet habe, das du mir gegeben hast, damit ich es tue.',
        5: 'Und jetzt, Vater, verherrliche du mich bei dir mit der Herrlichkeit, die ich bei dir hatte, bevor die Welt existierte.',
        6: 'Ich habe deinen Namen den Menschen bekannt gemacht, die du mir aus der Welt gegeben hast. Dir gehörten sie, und mir hast du sie gegeben, und dein Wort haben sie gehalten.',
        7: 'Jetzt haben sie erkannt, dass alles, was du mir gegeben hast, von dir ist;',
        8: 'denn die Worte, die du mir gegeben hast, habe ich ihnen gegeben, und sie haben sie angenommen, und sie haben tatsächlich erkannt, dass ich von dir ausgegangen bin, und sie haben geglaubt, dass du mich gesandt hast.',
        9: 'Ich bitte für sie – nicht für die Welt bitte ich, sondern für diejenigen, die du mir gegeben hast, weil sie dir gehören,',
        10: 'und alles, was meins [ist], ist deins, und was deins [ist], meins, und ich bin unter ihnen verherrlicht.',
        11: 'Ich bin ja nicht länger in der Welt, aber sie sind in der Welt, und ich komme zu dir. Heiliger Vater, bewahre sie in deinem Namen, den du mir gegeben hast, damit sie eins sind wie wir!',
        12: 'Während ich bei ihnen war, bewahrte ich sie in deinem Namen, den du mir gegeben hast, und ich habe sie behütet, und keiner von ihnen ging verloren außer dem Sohn des Verderbens, damit sich die Schrift erfüllt.',
        13: 'Aber jetzt komme ich zu dir, und diese [Dinge] rede ich in der Welt, damit sie meine Freude haben, in ihnen erfüllt.',
        14: 'Ich habe ihnen dein Wort gegeben, und die Welt hat sie gehasst, weil sie nicht von der Welt sind, so wie ich nicht von der Welt bin.',
        15: 'Ich bitte nicht, dass du sie aus der Welt nimmst, sondern dass du sie vor dem Bösen bewahrst.',
        16: 'Sie sind nicht von der Welt, so wie ich nicht von der Welt bin.',
        17: 'Heilige sie durch die Wahrheit! Dein Wort ist Wahrheit.',
        18: 'Wie du mich in die Welt gesandt hast, so habe auch ich sie in die Welt gesandt.',
        19: 'Und für sie heilige ich mich selbst, damit auch sie geheiligt sind durch Wahrheit.',
        20: 'Aber nicht nur für sie bitte ich, sondern auch für diejenigen, die durch ihr Wort an mich glauben;',
        21: 'damit sie alle eins sind, so wie du, Vater, in mir [bist] und ich in dir, sodass auch sie in uns sind; damit die Welt glaubt, dass du mich gesandt hast.',
        22: 'Und ich habe die Herrlichkeit, die du mir gegeben hast, ihnen gegeben, damit sie eins sind, so wie wir eins [sind] –',
        23: 'ich in ihnen und du in mir, damit sie in eins vollendet sind, damit die Welt erkennt, dass du mich gesandt und sie geliebt hast, so wie du mich geliebt hast.',
        24: 'Vater, was du mir gegeben hast … ich will, dass da, wo ich bin, auch sie bei mir sind, damit sie meine Herrlichkeit sehen, die du mir gegeben hast, weil du mich [schon] vor Gründung der Welt geliebt hast.',
        25: 'Gerechter Vater, die Welt hat dich nicht erkannt, ich aber habe dich erkannt, und sie haben erkannt, dass du mich gesandt hast.',
        26: 'Und ich habe ihnen deinen Namen bekannt gemacht, und ich werde ihn [weiterhin] bekannt machen, damit die Liebe, mit der du mich geliebt hast, in ihnen ist und ich in ihnen.“',
    },
    18: {
        1: 'Nachdem er diese [Dinge] gesagt hatte, ging Jesus zusammen mit seinen Jüngern hinaus, jenseits des Wadi Kidron, wo ein Garten war, in den er und seine Jünger hineingingen.',
        2: 'Aber auch Judas, der ihn verriet, kannte den Ort, weil sich Jesus dort oft mit seinen Jüngern versammelte.',
        3: 'Judas, der die Kohorte und Tempeldiener von den Oberpriestern und Pharisäern erhalten hatte, kommt nun mit Laternen und Fackeln und Waffen dorthin.',
        4: 'Jesus, der alles wusste, was auf ihn zukommen würde, ging also hinaus und sagt zu ihnen: „Wen sucht ihr?“',
        5: 'Sie antworteten ihm: „Jesus, den Nazoräer.“Er sagt zu ihnen: „Ich bin es.“Es stand aber auch Judas, der ihn verriet, bei ihnen.',
        6: 'Wie er nun zu ihnen sagte: „Ich bin es“, wichen sie zurück und fielen zu Boden.',
        7: 'Erneut fragte er sie also: „Wen sucht ihr?“Sie aber sagten: „Jesus, den Nazoräer.“',
        8: 'Jesus antwortete: „Ich habe euch gesagt, dass ich es bin. Wenn ihr also mich sucht, dann lasst sie gehen!“,',
        9: 'damit sich das Wort erfüllt, das er gesagt hatte: „Von denen, die du mir gegeben hast, habe ich nicht einen verloren.“',
        10: 'Simon Petrus, der ein Schwert hatte, zog es nun, und er schlug den Knecht des Oberpriesters, und er hieb sein rechtes Ohr ab (der Knecht hatte aber den Namen Malchus).',
        11: 'Da sagte Jesus zu Petrus: „Tu das Schwert in die Scheide! Den Becher, den mir der Vater gegeben hat, … soll ich ihn etwa nicht trinken?“',
        12: 'Die Kohorte und der Hauptmann und die Tempeldiener der Judäer verhaften Jesus also, und sie fesselten ihn,',
        13: 'und sie führten ihn zunächst zu Hannas; denn er war der Schwiegervater von Kajaphas, der in jenem Jahr Oberpriester war.',
        14: 'Es war aber Kajaphas, der den Judäern geraten hatte, es sei besser, dass ein einziger Mensch anstelle des Volkes stirbt.',
        15: 'Und Simon Petrus und ein anderer Jünger folgten Jesus. Jener Jünger aber war dem Oberpriester bekannt, und er ging mit Jesus hinein in den Hof des Oberpriesters.',
        16: 'Petrus aber blieb draußen vor der Tür stehen. Also ging der andere Jünger hinaus (der, der ein Bekannter des Oberpriesters [war]), und er sprach mit der Türhüterin, und er führte Petrus hinein.',
        17: 'Da sagt die Magd, die Türhüterin, zu Petrus: „Bist du nicht auch [einer] von den Jüngern dieses Mannes?“Jener sagt: „Bin ich nicht!“',
        18: 'Es standen da aber die Knechte und die Tempeldiener, die ein Kohlenfeuer gemacht hatten, weil es kalt war, und sie wärmten sich; und auch Petrus stand bei ihnen und wärmte sich.',
        19: 'Der Oberpriester fragte Jesus also über seine Jünger und über seine Lehre.',
        20: 'Jesus antwortete ihm: „Ich habe öffentlich zur Welt geredet; ich habe immer in der Synagoge und im Tempel gelehrt, wo alle Judäer zusammenkommen, aber im Verborgenen habe ich nichts geredet.',
        21: 'Warum fragst du mich? Frage diejenigen, die gehört haben, was ich zu ihnen geredet habe! Siehe!, diese wissen, was ich gesagt habe.“',
        22: 'Als er dies nun sagte, gab einer der Tempeldiener, der dabeistand, Jesus eine Ohrfeige und sagte: „So antwortest du dem Oberpriester?“',
        23: 'Jesus antwortete ihm: „Wenn ich ungehörig geredet habe, dann bezeuge das Ungehörige; aber wenn [ich] zu Recht [gesprochen habe], warum schlägst du mich?“',
        24: 'Da sandte ihn Hannas gefesselt zu Kajaphas, dem Oberpriester.',
        25: 'Simon Petrus stand nun da und wärmte sich. Da sagten sie zu ihm: „Bist du nicht auch [einer] von seinen Jüngern?“Jener leugnete es, und er sagte: „Bin ich nicht!“',
        26: 'Einer von den Knechten des Oberpriesters (er war ein Verwandter dessen, dem Petrus das Ohr abgehauen hatte) sagt: „Habe ich dich nicht in dem Garten bei ihm gesehen?“',
        27: 'Da leugnete Petrus erneut, und prompt krähte ein Hahn.',
        28: 'Sie führen Jesus nun von Kajaphas in das Prätorium; es war aber früh am Morgen. Und sie selbst gingen nicht in das Prätorium hinein, um nicht verunreinigt zu werden, sondern das Passa essen zu können.',
        29: 'Also ging Pilatus zu ihnen nach draußen, und er sagt: „Welche Anklage bringt ihr gegen diesen Menschen vor?“',
        30: 'Sie antworteten und sagten zu ihm: „Wenn dieser kein Übeltäter wäre, würden wir ihn dir nicht ausliefern!“',
        31: 'Da sagte Pilatus zu ihnen: „Nehmt ihr ihn und richtet ihn nach eurem Gesetz!“Die Judäer sagten zu ihm: „Uns ist es nicht erlaubt, jemanden zu töten!“,',
        32: 'sodass sich das Wort von Jesus erfüllte, das er gesagt hatte, um andeuten, durch welchen Tod er sterben würde.',
        33: 'Pilatus ging dann wieder in das Prätorium hinein, und er rief Jesus, und er sagte zu ihm: „Bist du der König der Judäer?“',
        34: 'Jesus antwortete: „Sagst du das von dir aus, oder haben es dir andere über mich gesagt?“',
        35: 'Pilatus antwortete: „Bin ich etwa ein Judäer? Dein Volk und die Oberpriester haben dich mir ausgeliefert! Was hast du getan?“',
        36: 'Jesus antwortete: „Mein Königreich ist nicht von dieser Welt; wenn mein Königreich von dieser Welt wäre, dann würden meine Diener kämpfen, damit ich den Judäern nicht ausgeliefert werde; tatsächlich aber ist mein Königreich nicht von hier.“',
        37: 'Da sagte Pilatus zu ihm: „Also bist du doch ein König?“Jesus antwortete: „Du sagst, dass ich ein König sei. Ich bin dazu geboren und dazu in die Welt gekommen, um für die Wahrheit Zeugnis abzulegen. Jeder, der aus der Wahrheit ist, hört auf meine Stimme.“',
        38: 'Pilatus sagt zu ihm: „Was ist Wahrheit?“Und nachdem er dies gesagt hatte, ging er wieder hinaus zu den Judäern, und er sagt zu ihnen: „Ich finde keinerlei Schuld an ihm.',
        39: 'Ihr habt aber einen Brauch, dass ich euch am Passa einen [Gefangenen] freilasse; wollt ihr also, [dass] ich euch den König der Judäer freilasse?“',
        40: 'Da schrien sie wieder und sagten: „Nicht diesen, sondern Barabbas!“Barabbas war aber ein Räuber.',
    },
    19: {
        1: 'Daraufhin nahm Pilatus also Jesus, und er geißelte ihn.',
        2: 'Und die Soldaten flochten eine Krone aus Dornen und setzten sie auf seinen Kopf, und sie warfen ihm ein purpurrotes Gewand um,',
        3: 'und sie kamen zu ihm und sagten: „Sei gegrüßt, König der Judäer!“Dann gaben sie ihm Ohrfeigen.',
        4: 'Und Pilatus ging erneut nach draußen, und er sagt zu ihnen: „Siehe!, ich bringe ihn zu euch nach draußen, damit ihr wisst, dass ich keinerlei Schuld an ihm finde.“',
        5: 'Da kam Jesus nach draußen, wobei er die dornige Krone und das purpurrote Gewand trug. Und er sagt zu ihnen: „Siehe!, [da ist] der Mensch.“',
        6: 'Als ihn nun die Oberpriester und die Tempeldiener sahen, schrien sie und sagten: „Kreuzige [ihn], kreuzige [ihn]!“Pilatus sagt zu ihnen: „Nehmt ihr ihn und kreuzigt ihn, denn ich finde keine Schuld an ihm.“',
        7: 'Die Judäer antworteten ihm: „Wir haben ein Gesetz, und nach dem Gesetz muss er sterben, weil er sich selbst zum Sohn Gottes gemacht hat.“',
        8: 'Als nun Pilatus diese Begründung hörte, fürchtete er sich umso mehr,',
        9: 'und er ging wieder in das Prätorium hinein, und er sagt zu Jesus: „Woher bist du?“Jesus aber gab ihm keine Antwort.',
        10: 'Da sagt Pilatus zu ihm: „Mit mir redest du nicht? Weißt du nicht, dass ich Macht habe, dich freizulassen, und dass ich Macht habe, dich zu kreuzigen?“',
        11: 'Jesus antwortete ihm: „Du hättest keinerlei Macht über mich, wenn sie dir nicht von oben gegeben worden wäre; deshalb hat derjenige, der mich an dich ausgeliefert hat, größere Sünde.“',
        12: 'Von da an versuchte Pilatus, ihn freizulassen; die Judäer aber schrien und sagten: „Wenn du ihn freilässt, bist du kein Freund Cäsars; jeder, der sich selbst zum König macht, widerspricht Cäsar.“',
        13: 'Als nun Pilatus diese Worte hörte, führte er Jesus nach draußen, und er setzte sich auf den Richterstuhl, an der Stelle, die „Lithostrotos“heißt (auf Hebräisch wiederum „Gabbata“).',
        14: 'Es war aber Vorbereitungszeit für das Passa, es war etwa die sechste Stunde. Und er sagt zu den Judäern: „Siehe!, [da ist] euer König.“',
        15: 'Da schrien jene: „Nimm weg, nimm weg, kreuzige ihn!“Pilatus sagt zu ihnen: „Euren König soll ich kreuzigen?“Die Oberpriester antworteten: „Wir haben keinen König außer Cäsar!“',
        16: 'Daraufhin übergab er ihn also an sie, damit er gekreuzigt werde. Also übernahmen sie Jesus,',
        17: 'und er trug für sich selbst das Kreuz und ging hinaus zu der sogenannten „Schädelstätte“(das heißt auf Hebräisch „Golgota“),',
        18: 'wo sie ihn kreuzigten, und mit ihm zwei andere, ‹zu beiden Seiten›, und dazwischen Jesus.',
        19: 'Pilatus schrieb aber auch ein Schild, und er befestigte es an dem Kreuz; und [darauf] stand geschrieben: Jesus, der Nazoräer, der König der Judäer.',
        20: 'Dieses Schild lasen nun viele der Judäer, weil der Ort, wo Jesus gekreuzigt worden war, nahe der Stadt lag; und es war auf Hebräisch, Lateinisch [und] Griechisch geschrieben.',
        21: 'Da sagten die Oberpriester der Judäer zu Pilatus: „Schreibe nicht: ‚Der König der Judäer‘, sondern dass jener gesagt hat: ‚Ich bin der König der Judäer.‘“',
        22: 'Pilatus antwortete: „Was ich geschrieben habe, habe ich geschrieben.“',
        23: 'Die Soldaten – nachdem sie Jesus gekreuzigt hatten – nahmen nun seine Gewänder, und sie machten vier Teile [daraus], für jeden Soldaten einen Teil, [dazu] auch das Hemd. Es war aber das Hemd ohne Naht, von oben her ‹in eins durchgewebt›.',
        24: 'Da sagten sie zueinander: „Lasst es uns nicht zerreißen, sondern darum losen, wem es gehören soll“, sodass sich die Schrift erfüllte, die besagt: „Sie haben meine Gewänder unter sich aufgeteilt, und um meine Kleidung warfen sie das Los.“Die Soldaten taten nun [genau] das.',
        25: 'Es standen aber am Kreuz von Jesus seine Mutter und die Schwester seiner Mutter, Maria, die [Frau] des Klopas, und Maria Magdalena.',
        26: 'Als nun Jesus [seine] Mutter sah und den Jünger, den er besonders mochte, danebenstehen, sagt er zu [seiner] Mutter: „Frau, siehe!, [da ist] dein Sohn!“',
        27: 'Danach sagt er zu dem Jünger: „Siehe!, [da ist] deine Mutter.“Und von jener Stunde an nahm der Jünger sie ‹zu sich nach Hause›.',
        28: 'Danach, weil Jesus wusste, dass bereits alles vollbracht war, sagt er, damit die Schrift vollendet wird: „Ich habe Durst!“',
        29: 'Ein Gefäß voll saurem Wein stand [da]; also befestigten sie einen Schwamm voll saurem Wein um einen Ysopstängel und brachten ihn an seinen Mund.',
        30: 'Nachdem nun Jesus den sauren Wein genommen hatte, sagte er: „Es ist vollbracht!“, und er neigte den Kopf und gab den Geist auf.',
        31: 'Weil es Vorbereitungszeit war und damit die Leichname nicht während des Sabbats am Kreuz blieben (denn der Tag jenes Sabbats war groß), baten nun die Judäer Pilatus darum, dass ihre Beine gebrochen und sie abgenommen werden.',
        32: 'Da gingen die Soldaten, und von dem ersten brachen sie die Beine, auch von dem anderen, der zusammen mit ihm gekreuzigt worden war;',
        33: 'als sie aber zu Jesus kamen [und] sahen, dass er bereits gestorben war, brachen sie seine Beine nicht,',
        34: 'sondern einer der Soldaten durchbohrte seine Seite mit einer Lanze, und sofort kamen Blut und Wasser heraus.',
        35: 'Und der zugesehen hat, hat es bezeugt, und sein Zeugnis ist wahr, und jener weiß, dass er Wahres sagt, damit auch ihr glaubt.',
        36: 'Denn dies ist geschehen, damit sich die Schrift erfüllt: „Kein Knochen wird ihm gebrochen werden.“',
        37: 'Und außerdem besagt eine andere Schriftstelle: „Sie werden auf den sehen, den sie durchbohrt haben.“',
        38: 'Danach aber bat Josef von Arimatäa, der ein Jünger von Jesus war (ein verborgener aber aus Angst vor den Judäern), Pilatus [um Erlaubnis], den Leichnam von Jesus abzunehmen; und Pilatus gestattete es. Er kam also und nahm seinen Leichnam ab.',
        39: 'Es kam aber auch Nikodemus, der zuvor bei Nacht zu ihm gekommen war, und brachte eine Mixtur aus Myrrhe und Aloë, etwa hundert Pfund.',
        40: 'Da nahmen sie den Leichnam von Jesus, und sie wickelten ihn samt den Gewürzen in Leinentücher, wie es bei den Judäern Sitte ist zu bestatten.',
        41: 'Nun befand sich an dem Ort, wo er gekreuzigt worden war, ein Garten und in dem Garten eine neue Grabhöhle, in die noch nie jemand gelegt worden war.',
        42: 'Dort also legten sie Jesus hin – wegen der Vorbereitungszeit der Judäer [und] weil die Grabhöhle nah war.',
    },
    20: {
        1: 'Am ersten [Tag] der Woche nun kommt Maria Magdalena frühmorgens, als es noch dunkel ist, zu der Grabhöhle, und sie sieht, dass der Stein von der Grabhöhle weggenommen ist.',
        2: 'Da läuft sie los und geht zu Simon Petrus und zu dem anderen Jünger (den Jesus lieb hatte), und sie sagt zu ihnen: „Sie haben den Herrn aus der Grabhöhle genommen, und wir wissen nicht, wo sie ihn hingelegt haben!“',
        3: 'Also brachen Petrus und der andere Jünger auf, und sie gingen zu der Grabhöhle.',
        4: 'Die beiden liefen zwar gemeinsam los; aber der andere Jünger lief voraus, schneller als Petrus, und er kam als Erster zu der Grabhöhle.',
        5: 'Und als er sich vorbeugte, sieht er die Leinentücher daliegen; er ging jedoch nicht hinein.',
        6: 'Da kommt auch Simon Petrus, der ihm folgte, und er ging in die Grabhöhle hinein, und er sieht die Leinentücher daliegen',
        7: 'und das Schweißtuch, das auf seinem Kopf gewesen war, nicht bei den Leinentüchern liegen, sondern eigens zusammengefaltet an einer Stelle.',
        8: 'Daraufhin ging nun auch der andere Jünger hinein, der als Erster an der Grabhöhle angekommen war, und er sah und glaubte.',
        9: 'Denn sie verstanden die Schrift noch nicht, dass er von den Toten auferstehen musste.',
        10: 'Also gingen die Jünger wieder heim.',
        11: 'Maria aber stand draußen vor der Grabhöhle und weinte. Während sie nun weinte, beugte sie sich in die Grabhöhle vor,',
        12: 'und sie sieht zwei Engel in weißen [Kleidern] dasitzen, einen am Kopfende und einen am Fußende, wo der Leichnam von Jesus gelegen hatte.',
        13: 'Und jene sagen zu ihr: „Frau, warum weinst du?“Sie sagt zu ihnen: „Sie haben meinen Herrn weggenommen, und ich weiß nicht, wo sie ihn hingelegt haben.“',
        14: 'Nachdem sie dies gesagt hatte, drehte sie sich um, und sie sieht Jesus dastehen, aber sie wusste nicht, dass es Jesus war.',
        15: 'Jesus sagt zu ihr: „Frau, warum weinst du? Wen suchst du?“Da sie meinte, dass er der Gärtner sei, sagt sie zu ihm: „Herr, wenn du ihn weggetragen hast, dann sag mir, wo du ihn hingelegt hast, und ich werde ihn holen!“',
        16: 'Jesus sagt zu ihr: „Maria!“Nachdem sie sich umgedreht hatte, sagt sie zu ihm auf Hebräisch: „Rabbuni!“(das heißt: Lehrer).',
        17: 'Jesus sagt zu ihr: „Berühre mich nicht, denn ich bin noch nicht hinaufgestiegen zum Vater! Geh aber zu meinen Brüdern und sag ihnen: ‚Ich steige hinauf zu meinem Vater und eurem Vater, zu meinem Gott und eurem Gott.‘“',
        18: 'Maria Magdalena geht und berichtet den Jüngern: „Ich habe den Herrn gesehen!“, und diese [Dinge] hatte er zu ihr gesagt.',
        19: 'Als es nun Abend wurde, an jenem ersten Tag der Woche, und die Türen verschlossen waren, wo die Jünger aus Angst vor den Judäern waren, da kam Jesus und trat in die Mitte, und er sagt zu ihnen: „Friede [sei mit] euch!“',
        20: 'Und nachdem er dies gesagt hatte, zeigte er ihnen die Hände und die Seite. Da freuten sich die Jünger, als sie den Herrn sahen.',
        21: 'Darauf sagte Jesus erneut zu ihnen: „Friede [sei mit] euch! Wie mich der Vater gesandt hat, so schicke auch ich euch!“',
        22: 'Und nachdem er dies gesagt hatte, hauchte er sie an, und er sagt zu ihnen: „Nehmt den heiligen Geist!',
        23: 'Wessen Sünden auch immer ihr vergebt, denen sind sie vergeben; wessen Sünden ihr festhaltet, denen bleiben sie erhalten.“',
        24: 'Thomas aber, einer von den zwölf [Aposteln], der [auch] „Didymus“heißt, war nicht bei ihnen, als Jesus kam.',
        25: 'Also sagten die anderen Jünger zu ihm: „Wir haben den Herrn gesehen!“Er aber sagte zu ihnen: „Wenn ich nicht an seinen Händen den Abdruck der Nägel sehe und meinen Finger in den Abdruck der Nägel lege und meine Hand in seine Seite lege, dann werde ich es gewiss nicht glauben!“',
        26: 'Und acht Tage später waren seine Jünger wieder drinnen, und Thomas [war] bei ihnen. Jesus kommt, obwohl die Türen verschlossen sind, und er trat in die Mitte und sagte: „Friede [sei mit] euch!“',
        27: 'Danach sagt er zu Thomas: „Bring deinen Finger hierher und sieh meine Hände und bring deine Hand und lege sie in meine Seite, und werde nicht ungläubig, sondern gläubig!“',
        28: 'Thomas antwortete, und er sagte zu ihm: „Mein Herr und mein Gott!“',
        29: 'Jesus sagt zu ihm: „Weil du mich gesehen hast, hast du geglaubt? Beglückwünschenswert [sind], die nicht sehen und doch glauben!“',
        30: 'Nun tat Jesus zwar viele andere Zeichen vor seinen Jüngern, die nicht in diesem Buch geschrieben stehen;',
        31: 'diese aber stehen geschrieben, damit ihr glaubt, dass Jesus der Gesalbte ist, der Sohn Gottes, und damit ihr als Glaubende Leben habt in seinem Namen.',
    },
    21: {
        1: 'Danach gab sich Jesus am Meer von Tiberias den Jüngern erneut zu erkennen. Er gab sich aber folgendermaßen zu erkennen:',
        2: 'Es waren beisammen Simon Petrus und Thomas, der Didymos heißt, und Natanaël aus Kana in Galiläa und die [Söhne] des Zebedäus und zwei andere von seinen Jüngern.',
        3: 'Simon Petrus sagt zu ihnen: „Ich gehe fischen.“Sie sagen zu ihm: „Wir auch – wir kommen mit dir.“Sie gingen hinaus, und sie stiegen in das Boot, aber in jener Nacht fingen sie nichts.',
        4: 'Als es aber schon Morgen wurde, stellte sich Jesus an das Ufer; die Jünger wussten jedoch nicht, dass es Jesus war.',
        5: 'Da sagt Jesus zu ihnen: „Kinder, habt ihr nicht etwas Beilage?“Sie antworteten ihm: „Nein.“',
        6: 'Er aber sagte zu ihnen: „Werft das Netz auf der rechten Seite des Bootes aus, dann werdet ihr etwas finden!“Also warfen sie [das Netz] aus, aber sie konnten es nicht mehr einholen wegen der Menge der Fische.',
        7: 'Da sagt jener Jünger, den Jesus besonders mochte, zu Petrus: „Es ist der Herr!“Als nun Simon Petrus hörte, dass es der Herr sei, zog er das Gewand an (er war nämlich nackt), und er warf sich in das Meer,',
        8: 'die anderen Jünger aber kamen mit dem Boot (sie waren nämlich nicht weit vom Land entfernt, sondern [nur] etwa zweihundert Ellen) und schleppten das Netz mit den Fischen.',
        9: 'Als sie nun an Land stiegen, sehen sie ein Kohlenfeuer daliegen und Fisch daraufliegen und Brot.',
        10: 'Jesus sagt zu ihnen: „Bringt von den Fischen, die ihr gerade gefangen habt!“',
        11: 'Da stieg Simon Petrus hinauf, und er zog das Netz an Land, voll mit 153 großen Fischen. Und obwohl es so viele waren, riss das Netz nicht.',
        12: 'Jesus sagt zu ihnen: „Kommt her, frühstücken!“Aber keiner der Jünger wagte es, ihn zu fragen: „Wer bist du?“, da sie wussten, dass es der Herr war.',
        13: 'Jesus kommt, und er nimmt das Brot, und er gibt es ihnen, genauso auch den Fisch.',
        14: 'Dies [war] bereits das dritte [Mal], [dass] Jesus sich den Jüngern zu erkennen gab, nachdem er von den Toten auferweckt worden war.',
        15: 'Als sie nun gefrühstückt hatten, sagt Jesus zu Simon Petrus: „Simon, [Sohn] des Johannes, liebst du mich mehr als sie?“Er sagt zu ihm: „Ja, Herr, du weißt, dass ich dich lieb habe.“Er sagt zu ihm: „Weide meine Lämmer!“',
        16: 'Er sagt zu ihm wieder, ein zweites [Mal]: „Simon, [Sohn] des Johannes, liebst du mich?“Er sagt zu ihm: „Ja, Herr, du weißt, dass ich dich lieb habe.“Er sagt zu ihm: „Hüte meine Schafe!“',
        17: 'Ein drittes [Mal] sagt er zu ihm: „Simon, [Sohn] des Johannes, hast du mich lieb?“Petrus wurde traurig, dass er ein drittes [Mal] zu ihm sagte: „Hast du mich lieb?“Und er sagt zu ihm: „Herr, du weißt alles, du merkst [doch], dass ich dich lieb habe.“Jesus sagt zu ihm: „Weide meine Schafe!',
        18: 'Amen, amen, ich sage dir: Als du jünger warst, hast du dich selbst gegürtet und du bist gegangen, wohin du wolltest; aber wenn du alt geworden bist, wirst du deine Hände ausstrecken, und ein anderer wird dich gürten und wird dich bringen, wohin du nicht willst.“',
        19: '(Dies aber sagte er, um anzudeuten, mit welchem Tod er Gott verherrlichen würde.) Und nachdem er dies gesagt hatte, sagt er zu ihm: „Folge mir!“',
        20: 'Petrus drehte sich um und sieht den Jünger folgen, den Jesus besonders mochte [und] der auch bei dem Mahl an seiner Brust gelehnt und gesagt hatte: „Herr, wer ist es, der dich verrät?“',
        21: 'Als nun Petrus diesen sah, sagt er zu Jesus: „Herr, und was [wird aus] ihm?“',
        22: 'Jesus sagt zu ihm: „Wenn ich will, dass er [am Leben] bleibt, bis ich komme, was [kümmert es] dich? Folge du mir!“',
        23: 'Da ging dieses Wort zu den Geschwistern aus, dass jener Jünger nicht sterben würde. Jesus hatte aber nicht zu ihm gesagt, dass er nicht sterben würde, sondern: „Wenn ich will, dass er [am Leben] bleibt, bis ich komme, was [kümmert es] dich?“',
        24: 'Dies ist der Jünger, der Zeugnis darüber ablegt und der diese [Dinge] aufgeschrieben hat; und wir wissen, dass sein Zeugnis zuverlässig ist.',
        25: 'Es gibt aber noch viele andere [Dinge], die Jesus getan hat; wenn sie nacheinander aufgeschrieben würden, dann könnte auch die Welt selbst – denke ich – die Bücher nicht unterbringen, die zu schreiben wären.',
    },
}
